            keyboardModuleFound = type(keyboardModule) == "table",
            keyboardSeedAttempts = keyboardSeedAttempts,
            keyboardSeedSucceeded = keyboardSeedSucceeded,
            blockedTouchSwitches = blockedTouchSwitches,
            forcedKeyboardRestores = forcedKeyboardRestores,
            spoofReads = spoofReads,
            lastError = lastError,
        }
    end,
}
end
modules.camera=function(...)
local Players=game:GetService("Players")
local RunService=game:GetService("RunService")
local UserInputService=game:GetService("UserInputService")

local player=Players.LocalPlayer
local playerGui=player:WaitForChild("PlayerGui")
local BIND_NAME="__PCCameraTouchRightHalfGateV5"
-- Camera-only touch separation: once a finger starts on the movement joystick,
-- keep that entire finger excluded from camera input until it lifts.
local DEADZONE_RADIUS_SCALE=1.0

local oldCleanup=getgenv().__PCCameraTouchRightHalfGateV5Cleanup
if type(oldCleanup)=="function" then pcall(oldCleanup) end
pcall(function() RunService:UnbindFromRenderStep(BIND_NAME) end)

local playerModule=nil
local cameras=nil
local activeController=nil
local installedHooks={}
local hookEpoch=0
local blockedTouches=setmetatable({}, {__mode="k"})
local blockedTouchIds={}
local inputConnections={}
local leftBeginsBlocked=0
local leftChangesBlocked=0
local leftEndsBlocked=0
local rightBeginsPassed=0
local rightChangesPassed=0
local rightEndsPassed=0
local installErrors=0
local reinstallCount=0

local function isTouch(input)
    local t=nil
    pcall(function() t=input.UserInputType end)
    return t==Enum.UserInputType.Touch
end

local function touchPosition(input)
    local position=nil
    pcall(function() position=input.Position end)
    if typeof(position)=="Vector3" then
        return Vector2.new(position.X,position.Y)
    elseif typeof(position)=="Vector2" then
        return position
    end
    return nil
end

local function inJoystickDeadzone(input)
    local position=touchPosition(input)
    if not position then return false end

    -- Match the exact custom joystick by its current rendered rectangle.
    -- This avoids hit-test inconsistencies caused by the native-look image overlay,
    -- while not blocking the rest of the left half of the screen.
    local overlay=playerGui:FindFirstChild("PCKeyboardTouchBridgeV52Overlay")
    local joystick=overlay and overlay:FindFirstChild("PCJoystick",true)
    if not joystick or not joystick:IsA("GuiObject") then return false end

    local p=joystick.AbsolutePosition
    local s=joystick.AbsoluteSize
    return position.X>=p.X and position.X<=p.X+s.X
        and position.Y>=p.Y and position.Y<=p.Y+s.Y
end

local function getTouchId(input)
    local id=nil
    pcall(function() id=input.TouchId end)
    if type(id)=="number" then return id end
    return nil
end

local function bridgeOwnsTouch(input)
    local bridge=getgenv().PCKeyboardTouchBridgeV52
    return type(bridge)=="table" and type(bridge.OwnsTouch)=="function" and bridge.OwnsTouch(input)
end

local function isBlockedTouch(input)
    local id=getTouchId(input)
    return blockedTouches[input]==true
        or (id~=nil and blockedTouchIds[id]==true)
        or bridgeOwnsTouch(input)
end

-- Track touches at the global input layer, even when the joystick GUI captures
-- Began before BaseCamera sees it. Keep each touch blocked until that finger lifts.
inputConnections[#inputConnections+1]=UserInputService.InputBegan:Connect(function(input)
    if not isTouch(input) then return end

    -- Block only a touch that starts on the movement joystick.
    -- Do not suppress camera touches based on a global finger count: a stale
    -- count can make later touches appear ignored until a gesture settles.
    if inJoystickDeadzone(input) then
        blockedTouches[input]=true
        local id=getTouchId(input)
        if id~=nil then blockedTouchIds[id]=true end
    end
end)
inputConnections[#inputConnections+1]=UserInputService.InputEnded:Connect(function(input)
    if isTouch(input) then
        blockedTouches[input]=nil
        local id=getTouchId(input)
        if id~=nil then blockedTouchIds[id]=nil end
    end
end)

inputConnections[#inputConnections+1]=UserInputService.WindowFocusReleased:Connect(function()
    table.clear(blockedTouches)
    table.clear(blockedTouchIds)
end)

local function getMeta(tbl)
    local mt=nil
    if type(getrawmetatable)=="function" then pcall(function() mt=getrawmetatable(tbl) end) end
    if type(mt)~="table" then pcall(function() mt=getmetatable(tbl) end) end
    return type(mt)=="table" and mt or nil
end

local function findMethod(root,name)
    local seen={}
    local function visit(tbl,depth)
        if type(tbl)~="table" or depth>14 or seen[tbl] then return nil end
        seen[tbl]=true
        local own=nil
        pcall(function() own=rawget(tbl,name) end)
        if type(own)=="function" then
            return {fn=own,owner=tbl,name=name}
        end
        local index=nil
        pcall(function() index=rawget(tbl,"__index") end)
        local found=nil
        if type(index)=="table" then
            found=visit(index,depth+1)
            if found then return found end
        end
        local mt=getMeta(tbl)
        if mt then
            found=visit(mt,depth+1)
            if found then return found end
        end
        return nil
    end
    return visit(root,0)
end

local function getCameras()
    if type(cameras)=="table" then return cameras end
    local scripts=player:FindFirstChild("PlayerScripts")
    local moduleScript=scripts and scripts:FindFirstChild("PlayerModule")
    if not moduleScript then return nil end
    if type(playerModule)~="table" then
        pcall(function() playerModule=require(moduleScript) end)
    end
    if type(playerModule)~="table" then return nil end
    pcall(function()
        if type(playerModule.GetCameras)=="function" then cameras=playerModule:GetCameras() end
        if type(cameras)~="table" then cameras=rawget(playerModule,"cameras") end
    end)
    return cameras
end

local function getActiveController()
    local module=getCameras()
    if type(module)~="table" then return nil end
    local controller=rawget(module,"activeCameraController")
    if type(controller)~="table" and type(module.GetActiveCameraController)=="function" then
        pcall(function() controller=module:GetActiveCameraController() end)
    end
    return type(controller)=="table" and controller or nil
end

local function restoreHooks()
    hookEpoch+=1
    for i=#installedHooks,1,-1 do
        local h=installedHooks[i]
        if h.mode=="hookfunction" and type(hookfunction)=="function" then
            pcall(function() hookfunction(h.target,h.original) end)
        elseif h.mode=="rawset" and type(h.owner)=="table" and type(h.original)=="function" then
            if rawget(h.owner,h.name)==h.replacement then pcall(rawset,h.owner,h.name,h.original) end
        end
    end
    table.clear(installedHooks)
end

local function installOne(target,replacementFactory)
    if not target or type(target.fn)~="function" then return false end

    if type(hookfunction)=="function" then
        local original=nil
        local replacement=replacementFactory(function(...)
            return original(...)
        end)
        local ok,old=pcall(function() return hookfunction(target.fn,replacement) end)
        if ok and type(old)=="function" then
            original=old
            installedHooks[#installedHooks+1]={mode="hookfunction",target=target.fn,original=old}
            return true
        end
    end

    local previous=nil
    pcall(function() previous=rawget(target.owner,target.name) end)
    if type(previous)=="function" then
        local replacement=replacementFactory(previous)
        local ok=pcall(function() rawset(target.owner,target.name,replacement) end)
        if ok then
            installedHooks[#installedHooks+1]={mode="rawset",owner=target.owner,name=target.name,original=previous,replacement=replacement}
            return true
        end
    end

    installErrors+=1
    return false
end

local function installForController(controller)
    restoreHooks()
    blockedTouches=setmetatable({}, {__mode="k"})
    if type(controller)~="table" then return false end

    local epoch=hookEpoch
    local began=findMethod(controller,"OnInputBegan")
    local changed=findMethod(controller,"OnInputChanged")
    local ended=findMethod(controller,"OnInputEnded")

    local beganOk=installOne(began,function(callOriginal)
        return function(self,input,...)
            if epoch==hookEpoch and self==getActiveController() and isTouch(input) then
                if isBlockedTouch(input) or inJoystickDeadzone(input) then
                    blockedTouches[input]=true
                    local id=getTouchId(input)
                    if id~=nil then blockedTouchIds[id]=true end
                    leftBeginsBlocked+=1
                    return nil
                else
                    blockedTouches[input]=nil
                    rightBeginsPassed+=1
                end
            end
            return callOriginal(self,input,...)
        end
    end)

    local changedOk=installOne(changed,function(callOriginal)
        return function(self,input,...)
            if epoch==hookEpoch and self==getActiveController() and isTouch(input) then
                if isBlockedTouch(input) then
                    blockedTouches[input]=true
                    local id=getTouchId(input)
                    if id~=nil then blockedTouchIds[id]=true end
                    leftChangesBlocked+=1
                    return nil
                end

                -- Every non-joystick touch follows Roblox's original camera path across
                -- the ENTIRE screen. Never classify by left/right side or current position.
                rightChangesPassed+=1
            end
            return callOriginal(self,input,...)
        end
    end)

    local endedOk=installOne(ended,function(callOriginal)
        return function(self,input,...)
            if epoch==hookEpoch and self==getActiveController() and isTouch(input) then
                if isBlockedTouch(input) then
                    blockedTouches[input]=nil
                    local id=getTouchId(input)
                    if id~=nil then blockedTouchIds[id]=nil end
                    leftEndsBlocked+=1
                    return nil
                end
            end
            return callOriginal(self,input,...)
        end
    end)

    reinstallCount+=1
    return beganOk and changedOk and endedOk
end

activeController=getActiveController()
if activeController then
    pcall(function() installForController(activeController) end)
end

RunService:BindToRenderStep(BIND_NAME,Enum.RenderPriority.Camera.Value-6,function()
    local controller=getActiveController()
    if controller~=activeController then
        activeController=controller
        pcall(function() installForController(activeController) end)
    end
end)

getgenv().PCCameraTouchRightHalfGateV5={
    Version="6.1-fullscreen-normal-camera-except-joystick",
    DeadzoneRadiusScale=DEADZONE_RADIUS_SCALE,
    GetState=function()
        return {
            installedHooks=#installedHooks,
            reinstallCount=reinstallCount,
            installErrors=installErrors,
            leftBeginsBlocked=leftBeginsBlocked,
            leftChangesBlocked=leftChangesBlocked,
            leftEndsBlocked=leftEndsBlocked,
            rightBeginsPassed=rightBeginsPassed,
            rightChangesPassed=rightChangesPassed,
            rightEndsPassed=rightEndsPassed,
        }
    end,
}

getgenv().__PCCameraTouchRightHalfGateV5Cleanup=function()
    pcall(function() RunService:UnbindFromRenderStep(BIND_NAME) end)
    for _,connection in ipairs(inputConnections) do pcall(function() connection:Disconnect() end) end
    table.clear(inputConnections)
    table.clear(blockedTouchIds)
    restoreHooks()
    blockedTouches=setmetatable({}, {__mode="k"})
    getgenv().PCCameraTouchRightHalfGateV5=nil
    getgenv().__PCCameraTouchRightHalfGateV5Cleanup=nil
end
end
modules.wake=function(...)
local Players=game:GetService("Players")
local RunService=game:GetService("RunService")

local player=Players.LocalPlayer
local playerGui=player:WaitForChild("PlayerGui")

local BIND_NAME="__PCKeyboardControllerWakeV5"
local GUI_NAME="PCKeyboardControllerWakeV5Status"

local oldCleanup=getgenv().__PCKeyboardControllerWakeV5Cleanup
if type(oldCleanup)=="function" then pcall(oldCleanup) end
pcall(function() RunService:UnbindFromRenderStep(BIND_NAME) end)
local oldGui=playerGui:FindFirstChild(GUI_NAME)
if oldGui then oldGui:Destroy() end

local playerModule=nil
local controls=nil
local wakeAttempts=0
local updateCalls=0
local directEnableCalls=0
local wakeErrors=0
local lastStatus="starting"

pcall(function()
    local scripts=player:FindFirstChild("PlayerScripts")
    local moduleScript=scripts and scripts:FindFirstChild("PlayerModule")
    if moduleScript then playerModule=require(moduleScript) end
    if type(playerModule)=="table" then
        if type(playerModule.GetControls)=="function" then controls=playerModule:GetControls() end
        if type(controls)~="table" then controls=rawget(playerModule,"controls") end
    end
end)

local gui=Instance.new("ScreenGui")
gui.Name=GUI_NAME
gui.ResetOnSpawn=false
gui.IgnoreGuiInset=true
gui.DisplayOrder=10040
gui.Parent=playerGui

local label=Instance.new("TextLabel")
label.Name="WakeStatus"
label.BackgroundColor3=Color3.new(0,0,0)
label.BackgroundTransparency=0.28
label.TextColor3=Color3.new(1,1,1)
label.BorderSizePixel=0
label.Position=UDim2.fromOffset(8,34)
label.Size=UDim2.fromOffset(620,24)
label.Font=Enum.Font.Code
label.TextSize=12
label.TextXAlignment=Enum.TextXAlignment.Left
label.Text=" PC CTRL WAKE starting..."
label.Parent=gui

local function readEnabled(controller)
    if type(controller)~="table" then return nil end
    local value=nil
    pcall(function()
        value=rawget(controller,"enabled")
        if value==nil then value=rawget(controller,"Enabled") end
    end)
    return value
end

local lastAttemptController
local nextWakeAt=-math.huge
local function ensureEnabled()
    if type(controls)~="table" then
        lastStatus="controls-missing"
        return
    end

    local activeController=rawget(controls,"activeController")
    local activeModule=rawget(controls,"activeControlModule")
    local controlsEnabled=rawget(controls,"controlsEnabled")
    if type(activeController)~="table" or type(activeModule)~="table" then
        lastStatus="active-pc-controller-missing"
        return
    end

    local before=readEnabled(activeController)
    if before==true then
        nextWakeAt=-math.huge
        lastStatus="already-enabled"
        return
    end

    if controlsEnabled==false then
        nextWakeAt=-math.huge
        lastStatus="global-controls-disabled"
        return
    end
    local now=os.clock()
    if activeController==lastAttemptController and now<nextWakeAt then return end
    lastAttemptController,nextWakeAt=activeController,now+0.125
    wakeAttempts+=1

    -- First use Roblox's own ControlModule activation path. This is the least
    -- invasive correction and mirrors what SwitchToController is supposed to do.
    if controlsEnabled~=false and type(controls.UpdateActiveControlModuleEnabled)=="function" then
        local ok=pcall(function()
            controls:UpdateActiveControlModuleEnabled()
        end)
        if ok then updateCalls+=1 else wakeErrors+=1 end
    end

    local afterUpdate=readEnabled(activeController)
    if afterUpdate==true then
        lastStatus="enabled-by-controlmodule"
        return
    end

    -- If the selected keyboard controller is still asleep even though global
    -- controls are not disabled, wake that exact active controller. We do not
    -- touch Player:Move, Humanoid CFrame, WalkSpeed, camera, or Touch routing.
    if controlsEnabled~=false and type(activeController.Enable)=="function" then
        local ok=pcall(function()
            activeController:Enable(true)
        end)
        if ok then directEnableCalls+=1 else wakeErrors+=1 end
    end

    local final=readEnabled(activeController)
    if final==true then
        lastStatus="enabled-directly"
    elseif controlsEnabled==false then
        lastStatus="global-controls-disabled"
    else
        lastStatus="enable-failed"
    end
end

local displayedStatus,displayedEnabled,displayedGlobal,displayedAttempts
RunService:BindToRenderStep(BIND_NAME,Enum.RenderPriority.Input.Value-1,function()
    ensureEnabled()
    if not gui.Enabled then return end

    local controller=nil
    local global=nil
    local enabled=nil
    if type(controls)=="table" then
        controller=rawget(controls,"activeController")
        global=rawget(controls,"controlsEnabled")
        enabled=readEnabled(controller)
    end

    if displayedStatus==lastStatus and displayedEnabled==enabled and displayedGlobal==global
        and displayedAttempts==wakeAttempts then return end
    displayedStatus,displayedEnabled,displayedGlobal,displayedAttempts=lastStatus,enabled,global,wakeAttempts
    label.Text=string.format(
        " PC CTRL WAKE:%s  ctrlEn:%s global:%s attempts:%d CM:%d direct:%d err:%d",
        lastStatus,tostring(enabled),tostring(global),wakeAttempts,updateCalls,directEnableCalls,wakeErrors
    )
end)

getgenv().PCKeyboardControllerWakeV5={
    Version="5.5-enable-selected-keyboard-controller",
    GetState=function()
        local controller=type(controls)=="table" and rawget(controls,"activeController") or nil
        return {
            status=lastStatus,
            controllerEnabled=readEnabled(controller),
            controlsEnabled=type(controls)=="table" and rawget(controls,"controlsEnabled") or nil,
            wakeAttempts=wakeAttempts,
            updateCalls=updateCalls,
            directEnableCalls=directEnableCalls,
            errors=wakeErrors,
        }
    end,
}

getgenv().__PCKeyboardControllerWakeV5Cleanup=function()
    pcall(function() RunService:UnbindFromRenderStep(BIND_NAME) end)
    pcall(function() gui:Destroy() end)
    getgenv().PCKeyboardControllerWakeV5=nil
    getgenv().__PCKeyboardControllerWakeV5Cleanup=nil
end
end
modules.visual=function(...)
local Players=game:GetService("Players")
local Workspace=game:GetService("Workspace")
local UserInputService=game:GetService("UserInputService")

local player=Players.LocalPlayer
local playerGui=player:WaitForChild("PlayerGui")

-- Exact assets/crops used by Roblox's own fixed TouchThumbstick + TouchJump.
local THUMBSTICK_SHEET="rbxasset://textures/ui/TouchControlsSheet.png"
local JUMP_SHEET="rbxasset://textures/ui/Input/TouchControlsSheetV2.png"

local oldCleanup=getgenv().__PCRobloxNativeVisualV5Cleanup
if type(oldCleanup)=="function" then pcall(oldCleanup) end

local overlay=playerGui:FindFirstChild("PCKeyboardTouchBridgeV52Overlay")
if not overlay then
    overlay=playerGui:WaitForChild("PCKeyboardTouchBridgeV52Overlay",3)
end
if not overlay then error("PCKeyboardTouchBridgeV52Overlay missing") end

local joystick=overlay:FindFirstChild("PCJoystick",true)
local knob=joystick and joystick:FindFirstChild("Knob")
local jumpButton=overlay:FindFirstChild("PCJump",true)
if not joystick or not knob or not jumpButton then
    error("native visual targets missing")
end

-- Remember original properties once so cleanup is exact even after resize events.
local original=setmetatable({}, {__mode="k"})
local function setProp(instance,property,value)
    if not instance then return end
    local perInstance=original[instance]
    if not perInstance then
        perInstance={}
        original[instance]=perInstance
    end
    if perInstance[property]==nil then
        local ok,current=pcall(function() return instance[property] end)
        if ok then perInstance[property]={present=true,value=current} end
    end
    pcall(function() instance[property]=value end)
end

local created={}
local connections={}
local hiddenGuiStates=setmetatable({}, {__mode="k"})

local cameraViewportConnection
getgenv().__PCRobloxNativeVisualV5Cleanup=function()
    if cameraViewportConnection then
        pcall(function() cameraViewportConnection:Disconnect() end)
        cameraViewportConnection=nil
    end
    for _,connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
    end
    table.clear(connections)

    for _,instance in ipairs(created) do
        pcall(function() instance:Destroy() end)
    end
    table.clear(created)

    for instance,properties in pairs(original) do
        if instance and instance.Parent then
            for property,snapshot in pairs(properties) do
                if snapshot.present then
                    pcall(function() instance[property]=snapshot.value end)
                end
            end
        end
    end

    for gui,wasEnabled in pairs(hiddenGuiStates) do
        if gui and gui.Parent then
            pcall(function() gui.Enabled=wasEnabled end)
        end
    end

    getgenv().PCRobloxNativeVisualV5=nil
    getgenv().__PCRobloxNativeVisualV5Cleanup=nil
end

local function hideDebugGui(name)
    local gui=playerGui:FindFirstChild(name)
    if gui and gui:IsA("ScreenGui") then
        hiddenGuiStates[gui]=gui.Enabled
        gui.Enabled=false
    end
end

for _,name in ipairs({
    "PCModeLockV5Status",
    "PCKeyboardControllerWakeV5Status",
    "PCInputRouteProbeV54",
}) do
    hideDebugGui(name)
end

-- Remove the temporary custom look without touching its input connections.
setProp(joystick,"AnchorPoint",Vector2.new(0,0))
setProp(joystick,"BackgroundTransparency",1)
setProp(joystick,"Text","")
local joystickStroke=joystick:FindFirstChildOfClass("UIStroke")
if joystickStroke then setProp(joystickStroke,"Transparency",1) end

setProp(knob,"AnchorPoint",Vector2.new(0.5,0.5))
setProp(knob,"BackgroundTransparency",1)
local knobStroke=knob:FindFirstChildOfClass("UIStroke")
if knobStroke then setProp(knobStroke,"Transparency",1) end

setProp(jumpButton,"AnchorPoint",Vector2.new(0,0))
setProp(jumpButton,"BackgroundTransparency",1)
setProp(jumpButton,"Text","")
local jumpStroke=jumpButton:FindFirstChildOfClass("UIStroke")
if jumpStroke then setProp(jumpStroke,"Transparency",1) end

-- Roblox fixed thumbstick outer ring: TouchControlsSheet.png [0,0,220,220].
local outerImage=Instance.new("ImageLabel")
outerImage.Name="RobloxThumbstickOuter"
outerImage.BackgroundTransparency=1
outerImage.Image=THUMBSTICK_SHEET
outerImage.ImageRectOffset=Vector2.new(0,0)
outerImage.ImageRectSize=Vector2.new(220,220)
outerImage.ImageTransparency=0
outerImage.Position=UDim2.fromOffset(0,0)
outerImage.ZIndex=joystick.ZIndex
outerImage.Active=false
outerImage.Parent=joystick
created[#created+1]=outerImage

-- Roblox fixed thumbstick inner stick: same sheet [220,0,111,111].
local stickImage=Instance.new("ImageLabel")
stickImage.Name="RobloxThumbstickStick"
stickImage.BackgroundTransparency=1
stickImage.Image=THUMBSTICK_SHEET
stickImage.ImageRectOffset=Vector2.new(220,0)
stickImage.ImageRectSize=Vector2.new(111,111)
stickImage.ImageTransparency=0
stickImage.Size=UDim2.fromScale(1,1)
stickImage.Position=UDim2.fromScale(0,0)
stickImage.ZIndex=knob.ZIndex
stickImage.Active=false
stickImage.Parent=knob
created[#created+1]=stickImage

-- Roblox jump button: TouchControlsSheetV2.png regular [1,146,144,144].
local jumpImage=Instance.new("ImageLabel")
jumpImage.Name="RobloxJumpButton"
jumpImage.BackgroundTransparency=1
jumpImage.Image=JUMP_SHEET
jumpImage.ImageRectOffset=Vector2.new(1,146)
jumpImage.ImageRectSize=Vector2.new(144,144)
jumpImage.ImageTransparency=0
jumpImage.Size=UDim2.fromScale(1,1)
jumpImage.Position=UDim2.fromOffset(0,0)
jumpImage.ZIndex=jumpButton.ZIndex
jumpImage.Active=false
jumpImage.Parent=jumpButton
created[#created+1]=jumpImage

local function viewportSize()
    local camera=Workspace.CurrentCamera
    return camera and camera.ViewportSize or Vector2.new(896,414)
end

local function applyNativeLayout()
    local viewport=viewportSize()
    local minAxis=math.min(viewport.X,viewport.Y)
    local isSmallScreen=minAxis<=500

    -- Exact TouchThumbstick ResizeThumbstick sizing/placement from PlayerModule.
    local thumbstickSize=isSmallScreen and 70 or 120
    local thumbstickPosition=isSmallScreen
        and UDim2.new(0,(thumbstickSize/2)-10,1,-thumbstickSize-20)
        or UDim2.new(0,thumbstickSize/2,1,-thumbstickSize*1.75)

    setProp(joystick,"Size",UDim2.fromOffset(thumbstickSize,thumbstickSize))
    setProp(joystick,"Position",thumbstickPosition)
    outerImage.Size=UDim2.fromOffset(thumbstickSize,thumbstickSize)

    setProp(knob,"Size",UDim2.fromOffset(thumbstickSize/2,thumbstickSize/2))
    -- Keep the idle center identical to Roblox. The bridge will move this Frame
    -- from the same center while the finger is held.
    if getgenv().PCKeyboardTouchBridgeV52 then
        local state=nil
        pcall(function() state=getgenv().PCKeyboardTouchBridgeV52.GetState() end)
        if type(state)~="table" or state.movementTouchActive~=true then
            knob.Position=UDim2.fromOffset(thumbstickSize/2,thumbstickSize/2)
        end
    else
        knob.Position=UDim2.fromOffset(thumbstickSize/2,thumbstickSize/2)
    end

    -- Exact TouchJump ResizeJumpButton sizing/placement from PlayerModule.
    local jumpButtonSize=isSmallScreen and 70 or 120
    local jumpPosition=isSmallScreen
        and UDim2.new(1,-(jumpButtonSize*1.5-10),1,-jumpButtonSize-20)
        or UDim2.new(1,-(jumpButtonSize*1.5-10),1,-jumpButtonSize*1.75)

    setProp(jumpButton,"Size",UDim2.fromOffset(jumpButtonSize,jumpButtonSize))
    setProp(jumpButton,"Position",jumpPosition)
end

applyNativeLayout()

-- Match Roblox's pressed jump sprite.
connections[#connections+1]=jumpButton.InputBegan:Connect(function(input)
    if input.UserInputType==Enum.UserInputType.Touch then
        jumpImage.ImageRectOffset=Vector2.new(146,146)
    end
end)
connections[#connections+1]=jumpButton.InputEnded:Connect(function(input)
    if input.UserInputType==Enum.UserInputType.Touch then
        jumpImage.ImageRectOffset=Vector2.new(1,146)
    end
end)

local function bindCameraViewport()
    if cameraViewportConnection then
        pcall(function() cameraViewportConnection:Disconnect() end)
        cameraViewportConnection=nil
    end
    local camera=Workspace.CurrentCamera
    if camera then
        cameraViewportConnection=camera:GetPropertyChangedSignal("ViewportSize"):Connect(applyNativeLayout)
    end
    applyNativeLayout()
end
bindCameraViewport()
connections[#connections+1]=Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(bindCameraViewport)

getgenv().PCRobloxNativeVisualV5={
    Version="5.7-exact-roblox-touchthumbstick-touchjump",
    GetState=function()
        local viewport=viewportSize()
        local isSmallScreen=math.min(viewport.X,viewport.Y)<=500
        return {
            thumbstickSheet=THUMBSTICK_SHEET,
            jumpSheet=JUMP_SHEET,
            isSmallScreen=isSmallScreen,
            nativeSize=isSmallScreen and 70 or 120,
            debugHidden=true,
        }
    end,
}
end
modules.posture=(function()
-- Read game-owned signals. The bridge never toggles crouch or fires an emote.
local EVADE_GAME_ID=3647333358
local FLAGS={
    Crouching="crouch",IsCrouching="crouch",Crouched="crouch",IsCrouched="crouch",
    Emoting="emote",IsEmoting="emote",EmotePlaying="emote",PlayingEmote="emote",
    DoingEmote="emote",IsDancing="emote",Dancing="emote",IsTaunting="emote",Taunting="emote",
}
local EMOTE_NAMES={
    ["broom of dom"]=true,["rockin' stride"]=true,["rockin stride"]=true,["zombie stride"]=true,
}

local function animationKind(name)
    name=string.lower((string.gsub(name,"(%l)(%u)","%1 %2")))
    if name=="crouch" or name=="crouching" or name=="crouch idle" or name=="crouch walk" or name=="crouch move" then
        return "crouch"
    end
    if name=="emote" or name=="dance" or name=="taunt" or EMOTE_NAMES[name]
        or string.match(name,"^emote[%s_:%-]") then
        return "emote"
    end
end

local function disconnect(connections)
    for _,connection in ipairs(connections) do connection:Disconnect() end
    table.clear(connections)
end

return function(onChange)
    local player=game:GetService("Players").LocalPlayer
    local gui=assert(player:FindFirstChild("PlayerGui"))
    local session,charSignals,humSignals,animSignals,hudSignals={},{},{},{},{}
    local charFlags,humFlags,tracks={},{},{}
    local character,humanoid,animator,stand
    local keybind,legacyHeld,keybindConnection
    local crouchTracks,emoteTracks=0,0
    local lastSource
    local active=true

    local function readFlag(kind)
        local seen=false
        for name,category in pairs(FLAGS) do
            if category==kind then
                local c=character and character:GetAttribute(name)
                local h=humanoid and humanoid:GetAttribute(name)
                local cValue=charFlags[name]
                local hValue=humFlags[name]
                local cv=cValue and cValue.object.Value
                local hv=hValue and hValue.object.Value
                if c==true or c==1 or h==true or h==1 or cv==true or hv==true then return true end
                if c==false or c==0 or h==false or h==0 or cv==false or hv==false then seen=true end
            end
        end
        if seen then return false end
    end

    local function publish()
        if not active then return end
        local source="unknown"
        if character then
            local crouched=readFlag("crouch")
            local emoting=readFlag("emote")
            if crouched then source="crouch:flag"
            elseif emoting then source="emote:flag"
            elseif crouched==nil and stand and stand.Visible then source="crouch:hud"
            elseif crouched==nil and crouchTracks>0 then source="crouch:animation"
            elseif crouched==nil and legacyHeld==true then source="crouch:keybind"
            elseif emoting==nil and emoteTracks>0 then source="emote:animation"
            elseif crouched==false or emoting==false then source="standing:flag"
            elseif stand then source="standing:hud"
            end
        end
        if source~=lastSource then
            lastSource=source
            onChange(source:sub(1,7)=="crouch:" or source:sub(1,6)=="emote:",source)
        end
    end

    local function trackAnimation(track)
        if tracks[track] then return end
        local kind=animationKind(track.Name)
        if not kind and track.Animation then kind=animationKind(track.Animation.Name) end
        if not kind then return end
        if kind=="crouch" then crouchTracks+=1 else emoteTracks+=1 end
        local connections={}
        tracks[track]=connections
        local function ended()
            if tracks[track]~=connections then return end
            tracks[track]=nil
            disconnect(connections)
            if kind=="crouch" then crouchTracks-=1 else emoteTracks-=1 end
            publish()
        end
        connections[1]=track.Stopped:Connect(ended)
        connections[2]=track.Destroying:Connect(ended)
    end

    local function bindAnimator(value)
        if animator==value then return end
        disconnect(animSignals)
        for _,connections in pairs(tracks) do disconnect(connections) end
        table.clear(tracks)
        crouchTracks,emoteTracks=0,0
        animator=value
        if animator then
            animSignals[1]=animator.AnimationPlayed:Connect(function(track)
                trackAnimation(track)
                publish()
            end)
            local ok,playing=pcall(animator.GetPlayingAnimationTracks,animator)
            if ok then
                for _,track in ipairs(playing) do
                    if track.IsPlaying then trackAnimation(track) end
                end
            end
        end
    end

    local function detachFlags(values)
        for _,entry in pairs(values) do entry.connection:Disconnect() end
        table.clear(values)
    end

    local function bindFlags(owner,connections,values,onChild)
        if not owner then return end
        local function addFlag(child)
            if FLAGS[child.Name] and child:IsA("BoolValue") and not values[child.Name] then
                values[child.Name]={object=child,connection=child:GetPropertyChangedSignal("Value"):Connect(publish)}
            end
        end
        connections[#connections+1]=owner.AttributeChanged:Connect(function(name)
            if FLAGS[name] then publish() end
        end)
        connections[#connections+1]=owner.ChildAdded:Connect(function(child)
            addFlag(child)
            if onChild(child,false) or FLAGS[child.Name] then publish() end
        end)
        connections[#connections+1]=owner.ChildRemoved:Connect(function(child)
            local entry=values[child.Name]
            if entry and entry.object==child then
                entry.connection:Disconnect()
                values[child.Name]=nil
            end
            if onChild(child,true) or entry then publish() end
        end)
        for _,child in ipairs(owner:GetChildren()) do addFlag(child) end
    end

    local function bindHumanoid(value)
        if humanoid==value then return end
        disconnect(humSignals)
        detachFlags(humFlags)
        humanoid=value
        bindAnimator(value and value:FindFirstChildOfClass("Animator"))
        bindFlags(value,humSignals,humFlags,function(child,removing)
            if child:IsA("Animator") then
                if not removing and not animator then bindAnimator(child)
                elseif removing and child==animator then bindAnimator(nil) end
                return true
            end
            return false
        end)
    end

    local function bindCharacter(value)
        disconnect(charSignals)
        detachFlags(charFlags)
        character=value
        legacyHeld=nil
        bindHumanoid(value and value:FindFirstChildOfClass("Humanoid"))
        bindFlags(value,charSignals,charFlags,function(child,removing)
            if child:IsA("Humanoid") then
                if not removing and not humanoid then bindHumanoid(child)
                elseif removing and child==humanoid then bindHumanoid(nil) end
                return true
            end
            return false
        end)
        publish()
    end

    local function refreshHud(excluded)
        local controls=gui:FindFirstChild("ControlsGui",true)
        local frame=controls and controls:FindFirstChild("PCFrame",true)
        local value=frame and frame:FindFirstChild("Stand",true)
        -- DescendantRemoving can fire before the old hierarchy is unlinked.
        if excluded and value then
            local node=value
            while node do
                if node==excluded then value=nil break end
                node=node.Parent
            end
        end
        if value and not value:IsA("GuiObject") then value=nil end
        if stand==value then return end
        disconnect(hudSignals)
        stand=value
        if stand then hudSignals[1]=stand:GetPropertyChangedSignal("Visible"):Connect(publish) end
        publish()
    end

    local function refreshKeybind(excluded)
        local scripts=player:FindFirstChild("PlayerScripts")
        local events=scripts and scripts:FindFirstChild("Events")
        local value=events and events:FindFirstChild("KeybindUsed")
        if value and (excluded==scripts or excluded==events or excluded==value or not value:IsA("BindableEvent")) then
            value=nil
        end
        if keybind==value then return end
        if keybindConnection then keybindConnection:Disconnect() keybindConnection=nil end
        keybind,legacyHeld=value,nil
        if keybind then
            keybindConnection=keybind.Event:Connect(function(action,held)
                if active and character and action=="Crouch" and type(held)=="boolean" then
                    legacyHeld=held
                    publish()
                end
            end)
        end
        publish()
    end

    if game.GameId==EVADE_GAME_ID then
        local function isKeybindNode(node)
            return node.Name=="PlayerScripts" or node.Name=="Events" or node.Name=="KeybindUsed"
        end
        session[#session+1]=player.DescendantAdded:Connect(function(node)
            if isKeybindNode(node) then refreshKeybind() end
        end)
        session[#session+1]=player.DescendantRemoving:Connect(function(node)
            if isKeybindNode(node) then refreshKeybind(node) end
        end)
        refreshKeybind()
        local function isHudNode(node)
            return node.Name=="ControlsGui" or node.Name=="PCFrame" or node.Name=="Stand"
        end
        session[#session+1]=gui.DescendantAdded:Connect(function(node)
            if isHudNode(node) then refreshHud() end
        end)
        session[#session+1]=gui.DescendantRemoving:Connect(function(node)
            if isHudNode(node) then refreshHud(node) end
        end)
        refreshHud()
    end
    session[#session+1]=player.CharacterAdded:Connect(bindCharacter)
    session[#session+1]=player.CharacterRemoving:Connect(function(value)
        if character==value then bindCharacter(nil) end
    end)
    bindCharacter(player.Character)

    return function()
        if not active then return end
        active=false
        disconnect(session)
        disconnect(hudSignals)
        if keybindConnection then keybindConnection:Disconnect() keybindConnection=nil end
        keybind,stand=nil,nil
        bindCharacter(nil)
    end
end
end)()
modules.bridge=(function()
-- UI and sector geometry derived from the preserved V3.1 bridge.
return function(watchPosture)
    local Players=game:GetService("Players")
    local RunService=game:GetService("RunService")
    local inputService=game:GetService("UserInputService")
    local inputManager=game:GetService("VirtualInputManager")
    local player=Players.LocalPlayer
    local playerGui=assert(player:FindFirstChild("PlayerGui"))
    local env=getgenv()
    local BIND_NAME="__PCKeyboardTouchBridgeV52"
    local GUI_NAME="PCKeyboardTouchBridgeV52Overlay"
    local PRESS_THRESHOLD=0.30
    local SWEEP_STAGE_SECONDS=0.016
    local JUMP_BURST_SECONDS=0.200
    local KEY_CODES={Enum.KeyCode.W,Enum.KeyCode.A,Enum.KeyCode.S,Enum.KeyCode.D}
    local KEY_BITS={1,2,4,8}
    local CHORD_BITS={["-"]=0,W=1,A=2,S=4,D=8,["W+A"]=3,["W+D"]=9,
        ["W+A+D"]=11,["A+D"]=10,["A+S"]=6,["S+D"]=12}
    local BIT_CHORD={}
    for bits=0,15 do
        local names={}
        for index,name in ipairs({"W","A","S","D"}) do
            if bit32.btest(bits,KEY_BITS[index]) then names[#names+1]=name end
        end
        BIT_CHORD[bits]=#names==0 and "-" or table.concat(names,"+")
    end
    local STANDING={A="W+A",D="W+D",["W+A+D"]="W"}
    local LOW={["W+A"]="A",["W+D"]="D"}
    local SIDE={A=-1,["W+A"]=-1,D=1,["W+D"]=1}

    local previous=env.__PCKeyboardTouchBridgeV52Cleanup
    if type(previous)=="function" then previous() end
    local oldGui=playerGui:FindFirstChild(GUI_NAME)
    if oldGui then oldGui:Destroy() end

    local gui=Instance.new("ScreenGui")
    gui.Name=GUI_NAME
    gui.ResetOnSpawn=false
    gui.IgnoreGuiInset=true
    gui.DisplayOrder=10020
    gui.Parent=playerGui

    local joystick=Instance.new("TextButton")
    joystick.Name="PCJoystick"
    joystick.Text=""
    joystick.AutoButtonColor=false
    joystick.Active=true
    joystick.BackgroundColor3=Color3.fromRGB(55,55,55)
    joystick.BackgroundTransparency=0.48
    joystick.BorderSizePixel=0
    joystick.AnchorPoint=Vector2.new(0,1)
    joystick.Position=UDim2.new(0,42,1,-42)
    joystick.Size=UDim2.fromOffset(132,132)
    joystick.ZIndex=20
    joystick.Parent=gui
    local joystickCorner=Instance.new("UICorner")
    joystickCorner.CornerRadius=UDim.new(1,0)
    joystickCorner.Parent=joystick
    local joystickStroke=Instance.new("UIStroke")
    joystickStroke.Thickness=3
    joystickStroke.Transparency=0.35
    joystickStroke.Parent=joystick

    local knob=Instance.new("Frame")
    knob.Name="Knob"
    knob.BackgroundColor3=Color3.fromRGB(205,205,205)
    knob.BackgroundTransparency=0.22
    knob.BorderSizePixel=0
    knob.AnchorPoint=Vector2.new(0.5,0.5)
    knob.Position=UDim2.fromScale(0.5,0.5)
    knob.Size=UDim2.fromOffset(54,54)
    knob.ZIndex=21
    knob.Parent=joystick
    local knobCorner=Instance.new("UICorner")
    knobCorner.CornerRadius=UDim.new(1,0)
    knobCorner.Parent=knob

    local jumpButton=Instance.new("TextButton")
    jumpButton.Name="PCJump"
    jumpButton.Text="↑"
    jumpButton.Font=Enum.Font.GothamBold
    jumpButton.TextSize=35
    jumpButton.TextColor3=Color3.fromRGB(225,225,225)
    jumpButton.AutoButtonColor=false
    jumpButton.Active=true
    jumpButton.BackgroundColor3=Color3.fromRGB(55,55,55)
    jumpButton.BackgroundTransparency=0.46
    jumpButton.BorderSizePixel=0
    jumpButton.AnchorPoint=Vector2.new(1,1)
    jumpButton.Position=UDim2.new(1,-52,1,-122)
    jumpButton.Size=UDim2.fromOffset(86,86)
    jumpButton.ZIndex=20
    jumpButton.Parent=gui
    local jumpCorner=Instance.new("UICorner")
    jumpCorner.CornerRadius=UDim.new(1,0)
    jumpCorner.Parent=jumpButton
    local jumpStroke=Instance.new("UIStroke")
    jumpStroke.Thickness=3
    jumpStroke.Transparency=0.35
    jumpStroke.Parent=jumpButton

    local enabled=true
    local acceptingInput=true
    local connections={}
    local unwatch
    local touch,center
    local radius=46
    local x,z=0,0
    local low,postureSource=false,"unknown"
    local lateralLatch,centerExpires
    local target,applied,pressed="-","-",0
    local retryAt
    local sweepTarget,sweepAt
    local jumpConnection,jumpDeadline
    local spaceDown=false
    local knobTarget,knobOffset=Vector2.zero,Vector2.zero
    local movementCaptures,movementUpdates,keyEvents,jumpRequests,jumpPulses=0,0,0,0,0
    local evaluations,knobWrites,keyErrors=0,0,0

    local function sendKey(code,down)
        local ok=pcall(inputManager.SendKeyEvent,inputManager,down,code,false,game)
        if ok then keyEvents+=1 else keyErrors+=1 end
        return ok
    end

    local function applyChord(chord,now)
        applied=chord
        local wanted=CHORD_BITS[chord]
        if pressed==wanted then retryAt=nil return end
        -- V3.1 presses additions before removing old keys, including on pure A/D swaps.
        for i,code in ipairs(KEY_CODES) do
            local bit=KEY_BITS[i]
            if bit32.btest(wanted,bit) and not bit32.btest(pressed,bit) and sendKey(code,true) then
                pressed=bit32.bor(pressed,bit)
            end
        end
        for i,code in ipairs(KEY_CODES) do
            local bit=KEY_BITS[i]
            if bit32.btest(pressed,bit) and not bit32.btest(wanted,bit) and sendKey(code,false) then
                pressed=bit32.band(pressed,bit32.bnot(bit))
            end
        end
        retryAt=pressed~=wanted and now+1/30 or nil
    end

    local function chooseSector(now)
        local ax,az=math.abs(x),math.abs(z)
        local magnitudeSquared=x*x+z*z
        local horizontal=x<0 and "A" or "D"
        local inSideCorridor=az<=0.24

        if lateralLatch then
            if not inSideCorridor then
                lateralLatch,centerExpires=nil,nil
            elseif (lateralLatch=="A" and x>=0.08) or (lateralLatch=="D" and x<=-0.08) then
                lateralLatch,centerExpires=horizontal,nil
                return horizontal
            elseif magnitudeSquared>=PRESS_THRESHOLD^2 then
                centerExpires=nil
                return lateralLatch
            else
                centerExpires=centerExpires or now
                if now<=centerExpires then return lateralLatch end
                lateralLatch,centerExpires=nil,nil
            end
        end

        if magnitudeSquared<PRESS_THRESHOLD^2 then return "-" end
        if az<=0.0001 then
            lateralLatch=horizontal
            return horizontal
        end

        local ratio=ax/az
        if z<0 then
            if ax<=0.0001 then return "W" end
            if ratio<=0.34 then return "W+A+D" end
            if magnitudeSquared>=0.55^2 and ratio<=2.20 then
                return horizontal=="A" and "W+A" or "W+D"
            end
            if ratio<=1 then return "W" end
        else
            if ratio<0.65 then return "S" end
            if ratio<=1.54 then return horizontal=="A" and "A+S" or "S+D" end
        end
        if inSideCorridor then lateralLatch=horizontal end
        return horizontal
    end

    local function refreshKeys(now,modeChanged)
        evaluations+=1
        local sector=chooseSector(now)
        local mapped=(low and LOW or STANDING)[sector] or sector
        if mapped==target and not modeChanged then return end

        local previousSide=SIDE[target]
        local nextSide=SIDE[mapped]
        local turning=not modeChanged and not sweepTarget and z < -0.24
            and previousSide and nextSide and previousSide~=nextSide
        target=mapped
        sweepTarget,sweepAt=nil,nil
        if turning then
            sweepTarget,sweepAt=mapped,now+SWEEP_STAGE_SECONDS
            applyChord(low and "A+D" or "W+A+D",now)
        else
            applyChord(mapped,now)
        end
    end

    local config=env.PCMovementV32Config
    if type(config)=="table" and config.Profile==true and debug.profilebegin and debug.profileend then
        local evaluate=refreshKeys
        refreshKeys=function(now,modeChanged)
            debug.profilebegin("PC Movement V3.2 / Joystick")
            evaluate(now,modeChanged)
            debug.profileend()
        end
    end

    local function writeKnob()
        local size=joystick.AbsoluteSize
        knob.Position=UDim2.fromOffset(size.X/2+knobOffset.X,size.Y/2+knobOffset.Y)
        knobWrites+=1
    end

    local function updateKnobTarget(dx,dy)
        local size=joystick.AbsoluteSize
        local reach=math.max(1,math.min(size.X,size.Y)/2)
        local distanceSquared=dx*dx+dy*dy
        local scale=distanceSquared>reach*reach and reach/math.sqrt(distanceSquared) or 1
        knobTarget=Vector2.new(dx*scale,dy*scale)
    end

    local function updateMovement(position,begin)
        local dx,dy=position.X-center.X,position.Y-center.Y
        local newX,newZ=dx/radius,dy/radius
        if not begin and newX==x and newZ==z then return end
        x,z=newX,newZ
        movementUpdates+=1
        updateKnobTarget(dx,dy)
        if begin then
            knobOffset=knobTarget
            writeKnob()
        end
        refreshKeys(os.clock(),false)
    end

    local function releaseMovement(now)
        local owned=touch~=nil
        touch,center=nil,nil
        x,z=0,0
        lateralLatch,centerExpires=nil,nil
        sweepTarget,sweepAt=nil,nil
        target="-"
        applyChord("-",now)
        if owned then
            knobTarget,knobOffset=Vector2.zero,Vector2.zero
            knob.Position=UDim2.fromScale(0.5,0.5)
            knobWrites+=1
        end
    end

    local function stopJump()
        jumpDeadline=nil
        if jumpConnection then
            jumpConnection:Disconnect()
            jumpConnection=nil
        end
        if spaceDown and sendKey(Enum.KeyCode.Space,false) then spaceDown=false end
    end

    local function pulseJump()
        -- Keep the original up/down sequence, including the initial pulse.
        if sendKey(Enum.KeyCode.Space,false) then spaceDown=false end
        if sendKey(Enum.KeyCode.Space,true) then spaceDown=true end
        jumpPulses+=1
    end

    local function requestJump()
        jumpRequests+=1
        jumpDeadline=os.clock()+JUMP_BURST_SECONDS
        pulseJump()
        if not jumpConnection then
            jumpConnection=RunService.Heartbeat:Connect(function()
                if not jumpDeadline then return end
                if os.clock()>=jumpDeadline then stopJump() else pulseJump() end
            end)
        end
    end

    local function resetInput()
        releaseMovement(os.clock())
        stopJump()
    end

    local function containsPoint(control,position)
        if not control.Parent then return false end
        local p,s=control.AbsolutePosition,control.AbsoluteSize
        return position.X>=p.X and position.X<=p.X+s.X
            and position.Y>=p.Y and position.Y<=p.Y+s.Y
    end

    local api={}
    local function cleanup()
        if not enabled then return end
        enabled=false
        RunService:UnbindFromRenderStep(BIND_NAME)
        for _,connection in ipairs(connections) do connection:Disconnect() end
        table.clear(connections)
        if unwatch then unwatch() end
        resetInput()
        -- Give a transient injection failure one last chance before releasing ownership.
        if pressed~=0 then applyChord("-",os.clock()) end
        if spaceDown then stopJump() end
        gui:Destroy()
        if env.PCKeyboardTouchBridgeV52==api then env.PCKeyboardTouchBridgeV52=nil end
        if env.__PCKeyboardTouchBridgeV52Cleanup==cleanup then env.__PCKeyboardTouchBridgeV52Cleanup=nil end
    end
    env.__PCKeyboardTouchBridgeV52Cleanup=cleanup

    connections[#connections+1]=inputService.InputBegan:Connect(function(input)
        if not enabled or not acceptingInput or gui.Parent~=playerGui or input.UserInputType~=Enum.UserInputType.Touch then return end
        local position=input.Position
        if containsPoint(joystick,position) then
            if touch then return end
            touch=input
            local size=joystick.AbsoluteSize
            center=joystick.AbsolutePosition+size/2
            radius=math.max(46,math.min(size.X,size.Y)*0.42)
            movementCaptures+=1
            updateMovement(position,true)
        elseif containsPoint(jumpButton,position) then
            requestJump()
        end
    end)

    connections[#connections+1]=inputService.InputChanged:Connect(function(input)
        if enabled and input==touch then
            if input.UserInputState==Enum.UserInputState.Cancel then
                releaseMovement(os.clock())
            else
                updateMovement(input.Position,false)
            end
        end
    end)

    connections[#connections+1]=inputService.InputEnded:Connect(function(input)
        if enabled and input==touch then
            if input.UserInputState~=Enum.UserInputState.Cancel then updateMovement(input.Position,false) end
            releaseMovement(os.clock())
        end
    end)
    connections[#connections+1]=inputService.WindowFocusReleased:Connect(resetInput)
    connections[#connections+1]=player.CharacterRemoving:Connect(resetInput)
    connections[#connections+1]=joystick:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
        if touch then
            updateKnobTarget(x*radius,z*radius)
            writeKnob()
        end
    end)

    unwatch=watchPosture(function(isLow,source)
        if not enabled then return end
        postureSource=source
        if low~=isLow then
            low=isLow
            if touch then refreshKeys(os.clock(),true) end
        end
    end)

    RunService:BindToRenderStep(BIND_NAME,Enum.RenderPriority.Input.Value+8,function(dt)
        if not enabled then return end
        if sweepAt or centerExpires or retryAt or (spaceDown and not jumpConnection) then
            local now=os.clock()
            if centerExpires and now>centerExpires then refreshKeys(now,false) end
            if sweepAt and now>=sweepAt then
                local nextChord=sweepTarget
                sweepTarget,sweepAt=nil,nil
                applyChord(nextChord,now)
            end
            if retryAt and now>=retryAt then applyChord(applied,now) end
            if spaceDown and not jumpConnection then stopJump() end
        end
        if touch and knobOffset~=knobTarget then
            local step=math.clamp(dt or 1/60,0,0.05)
            knobOffset=knobOffset:Lerp(knobTarget,1-math.exp(-step/0.040))
            if (knobOffset-knobTarget).Magnitude<0.06 then knobOffset=knobTarget end
            writeKnob()
        end
    end)

    api.SuspendInput=function()
        if not enabled or not acceptingInput then return end
        acceptingInput=false
        resetInput()
    end
    api.Version="3.2-adaptive"
    api.OwnsTouch=function(input) return touch~=nil and touch==input end
    api.ReadMovement=function()
        return BIT_CHORD[pressed],x,z,sweepTarget~=nil,jumpPulses
    end
    api.GetState=function()
        return {chord=BIT_CHORD[pressed],analogX=x,analogZ=z,sweepActive=sweepTarget~=nil,
            movementTouchActive=touch~=nil,movementTouch=touch,movementCaptures=movementCaptures,
            movementUpdates=movementUpdates,keyEvents=keyEvents,keyErrors=keyErrors,jumpRequests=jumpRequests,
            jumpPulses=jumpPulses,bufferedJumpCount=0,jumpActive=jumpConnection~=nil,
            directPlayerMove=false,visibleJoystick=true,movementHalf=0.80,
            mode=low and "crouch-or-emote" or "standing",postureSource=postureSource,
            sectorEvaluations=evaluations,knobWrites=knobWrites}
    end
    env.PCKeyboardTouchBridgeV52=api
    return api
end
end)()
modules.assist=function(...)
-- Incremental V3.1 assist only. PC bootstrap/bridge/UI/jump/camera are unchanged.
-- Removes the old tangent/inward velocity motor and fabricated contact impulses.
-- Original V3.1 visual facing is retained; contact-hop is observed, not invented.
local Players=game:GetService("Players")
local RunService=game:GetService("RunService")
local Workspace=game:GetService("Workspace")
local PhysicsService=game:GetService("PhysicsService")
local HttpService=game:GetService("HttpService")

local player=Players.LocalPlayer
local EVADE_GAME_ID=3647333358
local env=getgenv()
local previousCleanup=env.__LegacyGridContactAssistV1Cleanup
if type(previousCleanup)=="function" then pcall(previousCleanup) end

local enabled=game.GameId==EVADE_GAME_ID
local character,humanoid,root=nil,nil,nil
local characterConnection,heartbeatConnection=nil,nil

-- Eight azimuths at each of the original four heights.
-- Local overlap fills the angular gaps; at most eight candidates are ray-checked.
local WALL_RADIUS=4.60
local WALL_RAYS=8
local WALL_HEIGHTS={-0.65,-0.08,0.52,1.15}
local CONTACT_MAX_DISTANCE=2.85
local CONTACT_SCAN_INTERVAL=1/20
local CONTACT_GRACE_SECONDS=0.105 -- display/history only, never force or jump
local WALL_NORMAL_Y_MAX=0.54
local OVERLAP_SCAN_INTERVAL=0.075
local OVERLAP_RAY_LIMIT=8

local FENCE_TOKENS={
    "fence","grid","grate","railing","rail","gate","cage",
    "cerca","grade","chainlink","chain_link","barricade","netting",
    "wirefence","fencing"
}
local COLLISION_TOKENS={"invisible","collision","clip","hitbox","barrier","blocker"}
local EXCLUDE_TOKENS={"boundary","border","mapedge","map_edge","worldedge","void",
    "killplane","kill_plane","outofbounds","out_of_bounds"}

local rayParams=RaycastParams.new()
rayParams.FilterType=Enum.RaycastFilterType.Exclude
rayParams.IgnoreWater=true
pcall(function() rayParams.RespectCanCollide=true end)

local overlapParams=OverlapParams.new()
overlapParams.FilterType=Enum.RaycastFilterType.Exclude
overlapParams.MaxParts=48
pcall(function() overlapParams.RespectCanCollide=true end)

local radialDirections={}
for i=0,WALL_RAYS-1 do
    local angle=math.pi*2*i/WALL_RAYS
    radialDirections[#radialDirections+1]=Vector3.new(math.cos(angle),0,math.sin(angle))
end

local lastContact,cachedContact,currentContact=nil,nil,nil
local lastContactUntil,lastScanAt,lastOverlapAt=-math.huge,-math.huge,-math.huge
local lastHeartbeatAt=os.clock()
local lastChord="-"
local lastFacing=Vector3.zero
local noContactFrames,geometryContacts,scanCount,contactFrames=0,0,0,0
local rayCount,overlapCount,bodyQueryCount=0,0,0
local lastRayHit,lastRayHitDistance=nil,math.huge
local touchingParts,bodyParts,candidates={},{},{}
local lastBodyRefresh=-math.huge
local lastObservedY,lastNativePulses=nil,nil
local lastRealContactAt=-math.huge
local verticalChangesNearGrid=0
local config=type(env.PCMovementV31PreservedConfig)=="table" and env.PCMovementV31PreservedConfig or {}
local v32Config=env.PCMovementV32Config
if type(v32Config)=="table" then config=v32Config end
local profile=config.Profile==true and debug.profilebegin and debug.profileend
local diagnostics=config.Diagnostics==true
local records,recordNext,recordSize={},1,0
local lastLogAt=-math.huge
local function record(kind,details)
    if not diagnostics then return end
    details=details or {}
    details.kind,details.time=kind,os.clock()
    records[recordNext]=details
    recordNext=recordNext%160+1
    recordSize=math.min(160,recordSize+1)
end
local function logs()
    local out={}
    local start=recordSize==160 and recordNext or 1
    for offset=0,recordSize-1 do out[#out+1]=records[(start+offset-1)%160+1] end
    return out
end

local function flat(v)
    return Vector3.new(v.X,0,v.Z)
end
local function flatUnit(v)
    local f=flat(v)
    return f.Magnitude>1e-5 and f.Unit or Vector3.zero
end
local function nameMatches(part,tokens)
    local node=part
    for _=1,7 do
        if not node then break end
        local name=string.lower(node.Name or "")
        for _,token in ipairs(tokens) do
            if string.find(name,token,1,true) then return true end
        end
        node=node.Parent
    end
    return false
end

-- Name recognition first, then a conservative geometric fallback for unnamed
-- thin slats/panels. Collision volumes are restricted by shape and size.
local function isFenceLike(part)
    if not part or not part:IsA("BasePart") or not part.CanCollide then return false,"non-solid" end
    if nameMatches(part,EXCLUDE_TOKENS) then return false,"boundary" end
    local ancestor=part.Parent
    for _=1,4 do
        if not ancestor then break end
        if ancestor:FindFirstChildOfClass("Humanoid") then return false,"character" end
        ancestor=ancestor.Parent
    end
    if part:IsA("TrussPart") then return false,"climbable" end
    local sz=part.Size
    local thin,wide=math.min(sz.X,sz.Z),math.max(sz.X,sz.Z)
    if sz.Y<=0.90 and thin>2.4 then return false,"floor" end
    if nameMatches(part,FENCE_TOKENS) then return true,"named" end
    local upright=sz.Y>=1.25 and sz.Y<=38
    local sensibleWidth=wide<=72
    if nameMatches(part,COLLISION_TOKENS) and upright and thin<=2.0 and sensibleWidth then
        return true,"hitbox"
    end
    local likelyFence=part.Material==Enum.Material.Metal
        or part.Material==Enum.Material.DiamondPlate
        or (part.Transparency>=0.12 and part.Transparency<=0.96)
    -- In V3.1 this followed the upright rejection and was unreachable.
    local horizontalRail=sz.Y<=0.65 and thin<=0.52 and wide>=1.40 and wide<=72
        and (likelyFence or part.Material==Enum.Material.Plastic)
    if horizontalRail then return true,"horizontal-rail" end
    if not upright or not sensibleWidth then return false,"none" end
    local shape=thin<=0.78 and (wide>=0.10 or sz.Y>=2.0)
    local plainSlat=thin<=0.42 and wide<=1.10 and sz.Y>=1.45
    -- MeshPart alone is not evidence: ordinary mesh walls used to match too.
    if shape and (likelyFence or plainSlat) then return true,"geometry" end
    if thin<=1.55 and part.Transparency>=0.96 then return true,"invisible-panel" end
    return false,"none"
end

local classification={}
local function classify(part)
    if not part then return false end
    local kind=classification[part]
    if kind==nil then
        local valid,label=isFenceLike(part)
        kind=valid and label or false
        classification[part]=kind
    end
    return kind~=false,kind
end

local function readPhysicalContacts(now)
    table.clear(touchingParts)
    if not character then return end
    if now-lastBodyRefresh>=0.5 then
        lastBodyRefresh=now
        table.clear(bodyParts)
        for _,part in ipairs(character:GetChildren()) do
            if #bodyParts>=24 then break end
            if part:IsA("BasePart") then bodyParts[#bodyParts+1]=part end
        end
    end
    local reads,checked=0,0
    for _,body in ipairs(bodyParts) do
        if body.Parent==character and body.CanCollide then
            reads+=1
            if reads>4 then break end
            bodyQueryCount+=1
            local ok,parts=pcall(function() return body:GetTouchingParts() end)
            if ok then
                for _,part in ipairs(parts) do
                    checked+=1
                    if checked>48 then return end
                    local valid=classify(part)
                    if valid then
                        local got,collidable=pcall(function()
                            return PhysicsService:CollisionGroupsAreCollidable(body.CollisionGroup,part.CollisionGroup)
                        end)
                        if got and collidable then touchingParts[part]=true end
                    end
                end
            end
        end
    end
end

local function cast(origin,direction)
    rayCount+=1
    return Workspace:Raycast(origin,direction,rayParams)
end

local function bindCharacter(char)
    character=char
    humanoid=char and char:FindFirstChildOfClass("Humanoid") or nil
    root=char and char:FindFirstChild("HumanoidRootPart") or nil
    rayParams.FilterDescendantsInstances=char and {char} or {}
    overlapParams.FilterDescendantsInstances=char and {char} or {}
    if root then
        pcall(function()
            rayParams.CollisionGroup=root.CollisionGroup
            overlapParams.CollisionGroup=root.CollisionGroup
        end)
    end
    lastContact=nil
    lastRayHit,lastRayHitDistance=nil,math.huge
    cachedContact=nil
    currentContact=nil
    table.clear(touchingParts)
    table.clear(bodyParts)
    lastBodyRefresh=-math.huge
    lastObservedY,lastNativePulses=nil,nil
    lastRealContactAt=-math.huge
    lastContactUntil=-math.huge
    lastScanAt=-math.huge
    lastOverlapAt=-math.huge
    lastChord="-"
    lastFacing=Vector3.zero

end
bindCharacter(player.Character)
characterConnection=player.CharacterAdded:Connect(bindCharacter)

local function readBridge()
    local b=env.PCKeyboardTouchBridgeV52
    if type(b)=="table" and type(b.ReadMovement)=="function" then return b.ReadMovement() end
    return "-",0,0,false,0
end

local function intentFromChord(chord)
    local cam=Workspace.CurrentCamera
    if not cam then return flatUnit(humanoid.MoveDirection) end
    local forward=flatUnit(cam.CFrame.LookVector)
    local right=flatUnit(cam.CFrame.RightVector)
    local x,z=0,0
    -- Preserve exact PC key chords from the ORIGINAL bridge.
    if string.find(chord,"W",1,true) then z+=1 end
    if string.find(chord,"S",1,true) then z-=1 end
    if string.find(chord,"A",1,true) then x-=1 end
    if string.find(chord,"D",1,true) then x+=1 end
    local wanted=forward*z+right*x
    if wanted.Magnitude>1e-5 then return wanted.Unit end
    return flatUnit(humanoid.MoveDirection)
end

local function visualFacingIntent(desired,chord,analogX,analogZ,sweepActive)
    if sweepActive then return desired end -- original A/D sweep stays exact
    if chord~="W+A" and chord~="W+D" and chord~="A+S" and chord~="S+D" then
        return desired -- pure A/D/W/S stay pure
    end
    local cam=Workspace.CurrentCamera
    if not cam then return desired end
    local a=flatUnit(flatUnit(cam.CFrame.RightVector)*analogX
        -flatUnit(cam.CFrame.LookVector)*analogZ)
    if a.Magnitude<0.1 or desired:Dot(a)<0.65 then return desired end
    return flatUnit(desired*0.72+a*0.28)
end

local function candidateContact(hit,origin)
    if not hit then return nil end
    local valid,kind=classify(hit.Instance)
    local dist=(hit.Position-origin).Magnitude
    if dist<lastRayHitDistance then
        lastRayHitDistance=dist
        lastRayHit=hit.Instance
    end
    if not valid or dist>CONTACT_MAX_DISTANCE
        or math.abs(hit.Normal.Y)>WALL_NORMAL_Y_MAX then return nil end
    local normal=flatUnit(hit.Normal)
    if normal.Magnitude<0.2 then return nil end
    -- Ensure the normal points from the wall toward the player.
    if normal:Dot(flat(origin-hit.Position))<0 then normal=-normal end
    return {
        normal=normal,
        distance=dist,
        instance=hit.Instance,
        name=hit.Instance:GetFullName(),
        mode=kind,
        held=false,
        touching=touchingParts[hit.Instance]==true,
        observedAt=lastScanAt
    }
end

local function nearer(a,b)
    return a.distance<b.distance
end

local function bestContact()
    if not root then return nil end
    lastRayHit,lastRayHitDistance=nil,math.huge
    local now=os.clock()
    table.clear(classification)
    readPhysicalContacts(now)
    local rootPos=root.Position
    local best=nil
    -- Real collidable body contact is stronger evidence than a nearby ray.
    -- Top/edge contact on a narrow rail is included, without treating the floor as a grid.
    for part in pairs(touchingParts) do
        local valid,kind=classify(part)
        if valid then
            local point=part.Position
            pcall(function() point=part:GetClosestPointOnSurface(rootPos) end)
            local distance=(rootPos-point).Magnitude
            local candidate={normal=flatUnit(rootPos-point),distance=distance,instance=part,
                name=part:GetFullName(),mode=kind.."-body-contact",held=false,touching=true,
                observedAt=now,score=distance}
            if not best or candidate.score<best.score then best=candidate end
        end
    end
    if best then return best end
    for _,height in ipairs(WALL_HEIGHTS) do
        local origin=rootPos+Vector3.new(0,height,0)
        for _,direction in ipairs(radialDirections) do
            local candidate=candidateContact(cast(origin,direction*WALL_RADIUS),origin)
            if candidate then
                local score=candidate.distance
                if lastContact and candidate.normal:Dot(lastContact.normal)<0.70 then score+=0.16 end
                candidate.score=score
                if not best or score<best.score then best=candidate end
            end
        end
    end
    if now-lastOverlapAt<OVERLAP_SCAN_INTERVAL then return best end
    lastOverlapAt=now
    overlapCount+=1
    local ok,parts=pcall(function()
        return Workspace:GetPartBoundsInRadius(rootPos,WALL_RADIUS,overlapParams)
    end)
    if not ok or type(parts)~="table" then return best end
    for index,part in ipairs(parts) do
        if index>48 then break end
        local valid=classify(part)
        if valid then
            local got,point=pcall(function() return part:GetClosestPointOnSurface(rootPos) end)
            if got and typeof(point)=="Vector3" then
                local distance=(point-rootPos).Magnitude
                if distance>0.08 and distance<WALL_RADIUS then
                    candidates[#candidates+1]={part=part,point=point,distance=distance}
                end
            end
        end
    end
    table.sort(candidates,nearer)
    local origin=rootPos+Vector3.new(0,0.12,0)
    for index,item in ipairs(candidates) do
        if index>OVERLAP_RAY_LIMIT then break end
        local direction=item.point-origin
        if direction.Magnitude>0.08 then
            local hit=cast(origin,direction.Unit*(direction.Magnitude+0.14))
            if hit and hit.Instance==item.part then
                local candidate=candidateContact(hit,origin)
                if candidate then
                    candidate.mode=candidate.mode.."-overlap"
                    candidate.score=candidate.distance
                    if not best or candidate.score<best.score then best=candidate end
                end
            end
        end
    end
    table.clear(candidates)
    return best
end

local function getContact(now)
    if now-lastScanAt>=CONTACT_SCAN_INTERVAL then
        lastScanAt=now
        scanCount+=1
        if profile then debug.profilebegin("PC Movement V3.2 / Assist scan") end
        cachedContact=bestContact()
        table.clear(classification)
        if profile then debug.profileend() end
        if cachedContact then
            lastContact=cachedContact
            lastContactUntil=now+CONTACT_GRACE_SECONDS
            if string.find(cachedContact.mode,"geometry",1,true)
                or string.find(cachedContact.mode,"invisible-panel",1,true) then
                geometryContacts+=1
            end
        end
    end
    if cachedContact and cachedContact.instance and cachedContact.instance.Parent
        and cachedContact.instance.CanCollide then return cachedContact end
    if lastContact and now<lastContactUntil then
        return {
            normal=lastContact.normal,
            distance=lastContact.distance,
            name=lastContact.name,
            mode=lastContact.mode,
            held=true,
            touching=false,
            observedAt=lastScanAt
        }
    end
    return nil
end

local function smoothFacing(desired,dt)
    if desired.Magnitude<0.5 or not root or root.Anchored then return end
    local target=desired.Unit
    -- Smooth only facing. Do not filter the physics input or the old A/D keys.
    -- In a complete about-face, the avatar turns faster instead of feeling heavy.
    local forward=flatUnit(root.CFrame.LookVector)
    local dot=forward.Magnitude>0 and forward:Dot(target) or 1
    local response=dot<-0.55 and 0.050 or 0.067
    local alpha=1-math.exp(-dt/response)
    local frame=CFrame.lookAt(root.Position,root.Position+target)
    pcall(function()
        root.CFrame=root.CFrame:Lerp(frame,alpha)
    end)
end

-- Observe the real contact/jump sequence. The original bridge remains the only
-- Space sender; this module cannot fabricate an air hop or race its 200ms burst.
local function observeContact(contact,now,jumpPulses)
    local velocity=root.AssemblyLinearVelocity
    local confirmed=contact and not contact.held and contact.touching==true
    if confirmed then lastRealContactAt=now end
    if lastObservedY and velocity.Y-lastObservedY>=0.75 and now-lastRealContactAt<=0.20 then
        verticalChangesNearGrid+=1
        if diagnostics then record("vertical_change_near_grid",{before=lastObservedY,after=velocity.Y,
            nativeJumpPulseChanged=lastNativePulses~=nil and jumpPulses~=lastNativePulses,
            grounded=humanoid.FloorMaterial~=Enum.Material.Air,source="unconfirmed"}) end
    end
    lastObservedY,lastNativePulses=velocity.Y,jumpPulses
    if diagnostics and now-lastLogAt>=0.15 then
        lastLogAt=now
        record("contact_sample",{chord=lastChord,horizontal=flat(velocity).Magnitude,vertical=velocity.Y,
            grounded=humanoid.FloorMaterial~=Enum.Material.Air,nearby=contact~=nil,
            contactConfirmed=confirmed and true or false,held=contact and contact.held or false,
            hit=contact and contact.name or "-",mode=contact and contact.mode or "none",jumpPulses=jumpPulses})
    end
end

heartbeatConnection=RunService.Heartbeat:Connect(function(dtFromHeartbeat)
    if not enabled then return end
    if character~=player.Character then bindCharacter(player.Character) end
    if character and (not humanoid or humanoid.Parent~=character or not root or root.Parent~=character) then
        local nextHum=character:FindFirstChildOfClass("Humanoid")
        local nextRoot=character:FindFirstChild("HumanoidRootPart")
        if nextHum~=humanoid or nextRoot~=root then bindCharacter(character) end
    end
    if not humanoid or not root then return end
    if humanoid.Health<=0 or humanoid.Sit or root.Anchored then return end

    local now=os.clock()
    local dt=math.clamp(dtFromHeartbeat or now-lastHeartbeatAt,1/240,0.05)
    lastHeartbeatAt=now
    local chord,rawX,rawZ,sweepActive,jumpPulses=readBridge()
    local desired=intentFromChord(chord)
    lastChord=chord

    -- Only orientation gets analog polish. The input/key engine is untouched.
    local visual=visualFacingIntent(desired,chord,rawX,rawZ,sweepActive)
    if visual.Magnitude>0.05 then
        smoothFacing(visual,dt)
    else
        lastFacing=Vector3.zero
    end
    if desired.Magnitude<=0.05 then
        currentContact=nil
        return
    end

    local contact=getContact(now)
    currentContact=contact
    observeContact(contact,now,jumpPulses)
    if not contact then
        noContactFrames+=1
        return
    end
    contactFrames+=1 -- observation, not a velocity correction
end)

local api={
    Version="3.2-preserved-light-contact",
    Enabled=enabled,
    SetDiagnostics=function(value) diagnostics=value==true return diagnostics end,
    GetLogs=logs,
    GetState=function()
        return {
            enabled=enabled,chord=lastChord,contactFrames=contactFrames,geometryContacts=geometryContacts,
            noContactFrames=noContactFrames,scanCount=scanCount,overlapPartLimit=overlapParams.MaxParts,
            mode=currentContact and currentContact.mode or "none",
            lastHitName=currentContact and currentContact.name or "-",
            lastRayHitName=lastRayHit and lastRayHit:GetFullName() or "-",lastRayHitDistance=lastRayHitDistance,
            lastNormal=currentContact and currentContact.normal or Vector3.zero,
            contactConfirmed=currentContact~=nil and not currentContact.held and currentContact.touching==true,
            contactSampleAge=lastScanAt~=-math.huge and math.max(0,os.clock()-lastScanAt) or nil,
            wallRadius=WALL_RADIUS,scanInterval=CONTACT_SCAN_INTERVAL,
            raysTotal=rayCount,overlapQueries=overlapCount,bodyQueries=bodyQueryCount,
            raycastBudgetPerScan=WALL_RAYS*#WALL_HEIGHTS+OVERLAP_RAY_LIMIT,
            horizontalWrites=0,verticalWrites=0,magnetFrames=0,
            microHopEnabled=false,contactHopEnabled=false,nativeJumpUnchanged=true,
            verticalChangesNearGrid=verticalChangesNearGrid,diagnostics=diagnostics,
            visualFacing="original-v31",physicsValidation="on-device-required"
        }
    end,
}
api.ExportDiagnostics=function(filename)
    local function scalarState(name)
        local object=env[name]
        if type(object)~="table" or type(object.GetState)~="function" then return nil end
        local ok,value=pcall(object.GetState)
        if not ok or type(value)~="table" then return nil end
        local out={}
        for key,item in pairs(value) do
            local kind=type(item)
            if type(key)=="string" and (kind=="boolean" or kind=="string"
                or (kind=="number" and item==item and math.abs(item)<math.huge)) then
                out[key]=item
            end
        end
        return out
    end
    local state=api.GetState()
    state.lastNormal={x=state.lastNormal.X,y=state.lastNormal.Y,z=state.lastNormal.Z}
    if state.lastRayHitDistance==math.huge then state.lastRayHitDistance=nil end
    local json=HttpService:JSONEncode({state=state,events=logs(),
        bridge=scalarState("PCKeyboardTouchBridgeV52"),pcLock=scalarState("PCModeLock"),
        keyboardWake=scalarState("PCKeyboardControllerWakeV5"),
        cameraGate=scalarState("PCCameraTouchRightHalfGateV5")})
    filename=filename or "PCMovement_V31_Preserved_Log.json"
    if type(writefile)=="function" then
        local ok,message=pcall(writefile,filename,json)
        if ok then return true,filename end
        return false,tostring(message),json
    end
    return false,"writefile unavailable",json
end
env.LegacyGridContactAssistV1=api
local cleanup
cleanup=function()
    enabled=false
    api.Enabled=false
    if heartbeatConnection then pcall(function() heartbeatConnection:Disconnect() end) end
    if characterConnection then pcall(function() characterConnection:Disconnect() end) end
    if env.LegacyGridContactAssistV1==api then env.LegacyGridContactAssistV1=nil end
    if env.__LegacyGridContactAssistV1Cleanup==cleanup then env.__LegacyGridContactAssistV1Cleanup=nil end
end
env.__LegacyGridContactAssistV1Cleanup=cleanup
end
modules.originalAssist=function(...)
-- PC MOVEMENT + ASSIST V3.1 / Evade mobile
-- V3 untouched: stronger fence adhesion and a controlled light contact-hop.
-- Original keyboard mapping and staged A-D transitions live in the V6 bridge.
-- This module only handles visual facing + conditional fence-contact physics.
-- A movement AWAY from the fence immediately releases the magnetic correction.
local Players=game:GetService("Players")
local RunService=game:GetService("RunService")
local Workspace=game:GetService("Workspace")

local player=Players.LocalPlayer
local EVADE_GAME_ID=3647333358
local env=getgenv()
local previousCleanup=env.__LegacyGridContactAssistV1Cleanup
if type(previousCleanup)=="function" then pcall(previousCleanup) end

local enabled=game.GameId==EVADE_GAME_ID
local character,humanoid,root=nil,nil,nil
local characterConnection,heartbeatConnection=nil,nil

-- Keep 360-degree coverage but fewer probes than V1 (112 vs 160 per scan).
local WALL_RADIUS=4.10
local WALL_RAYS=28
local WALL_HEIGHTS={-0.65,-0.08,0.52,1.15}
local CONTACT_MAX_DISTANCE=2.85
local CONTACT_SCAN_INTERVAL=1/30
local CONTACT_GRACE_SECONDS=0.105
local WALL_NORMAL_Y_MAX=0.54

-- Contact behavior: inward adhesion along walls, NEVER against outward input.
local MAGNET_INWARD_SPEED=2.75
local MAGNET_SPEED_CAP=4.6
local MAGNET_RESPONSE=0.038
-- Light contact-hop: approx. 0.17-0.18 s of flight at normal Roblox gravity.
-- Only a nearby eligible rail impact can trigger, never a general movement change.
local CONTACT_HOP_ENABLED=true
local HOP_MAX_CONTACT_DISTANCE=2.12
local HOP_TARGET_AIRTIME=0.175
local HOP_OUTWARD_SPEED=2.6
local HOP_RELEASE_SECONDS=0.085
local HOP_COOLDOWN_SECONDS=0.42
local HOP_REARM_LOST_SECONDS=0.15
local WALK_SEED_FACTOR=0.92
local MICRO_HOP_ENABLED=true -- preserve original small contact-hop mechanic
local MICRO_HOP_SPEED=4.25
local MICRO_HOP_COOLDOWN=0.14

local FENCE_TOKENS={
    "fence","grid","grate","railing","rail","gate","cage",
    "cerca","grade","chainlink","chain_link","barricade","netting",
    "wirefence","fencing"
}
local COLLISION_TOKENS={"invisible","collision","clip","hitbox","barrier","blocker"}
local EXCLUDE_TOKENS={"boundary","border","mapedge","map_edge","worldedge","void",
    "killplane","kill_plane","outofbounds","out_of_bounds"}

local rayParams=RaycastParams.new()
rayParams.FilterType=Enum.RaycastFilterType.Exclude
rayParams.IgnoreWater=true

local overlapParams=OverlapParams.new()
overlapParams.FilterType=Enum.RaycastFilterType.Exclude
overlapParams.MaxParts=48

local radialDirections={}
for i=0,WALL_RAYS-1 do
    local angle=math.pi*2*i/WALL_RAYS
    radialDirections[#radialDirections+1]=Vector3.new(math.cos(angle),0,math.sin(angle))
end

local lastContact=nil
local cachedContact=nil
local lastContactUntil=-math.huge
local lastScanAt=-math.huge
local lastOverlapAt=-math.huge
local lastHeartbeatAt=os.clock()
local lastMicroHopAt=-math.huge
local lastContactHopAt=-math.huge
local lastNearFenceAt=-math.huge
local nextMagnetAt=-math.huge
local hopArmed=true
local contactHopCount=0
local groundContactHops=0
local airContactHops=0
local outwardReleases=0
local lastChord="-"
local lastFacing=Vector3.zero
local assistedFrames=0
local magnetFrames=0
local reversalFrames=0
local noContactFrames=0
local geometryContacts=0
local scanCount=0
local lastRayHitName="-"
local lastRayHitDistance=math.huge

local function flat(v)
    return Vector3.new(v.X,0,v.Z)
end
local function flatUnit(v)
    local f=flat(v)
    return f.Magnitude>1e-5 and f.Unit or Vector3.zero
end
local function nameMatches(part,tokens)
    local node=part
    for _=1,7 do
        if not node then break end
        local name=string.lower(node.Name or "")
        for _,token in ipairs(tokens) do
            if string.find(name,token,1,true) then return true end
        end
        node=node.Parent
    end
    return false
end

-- Name recognition first, then a conservative geometric fallback for unnamed
-- thin slats/panels. Collision volumes are restricted by shape and size.
local function isFenceLike(part)
    if not part or not part:IsA("BasePart") then return false,"none" end
    if nameMatches(part,EXCLUDE_TOKENS) then return false,"boundary" end
    if nameMatches(part,FENCE_TOKENS) then return true,"named" end
    local sz=part.Size
    local thin=math.min(sz.X,sz.Z)
    local wide=math.max(sz.X,sz.Z)
    local upright=sz.Y>=1.25 and sz.Y<=38
    local sensibleWidth=wide<=72
    local solid=part.CanCollide
    if nameMatches(part,COLLISION_TOKENS) and solid
        and upright and thin<=2.0 and sensibleWidth then
        return true,"hitbox"
    end
    if not solid or not upright or not sensibleWidth then return false,"none" end

    -- Thin solid vertical columns, metal grates, mesh fences, translucent rails
    -- and slim collision panels with generic names such as "Part".
    local shape=thin<=0.78 and (wide>=0.10 or sz.Y>=2.0)
    local plainSlat=thin<=0.42 and wide<=1.10 and sz.Y>=1.45
    local likelyFence=part:IsA("MeshPart")
        or part.Material==Enum.Material.Metal
        or part.Material==Enum.Material.DiamondPlate
        or (part.Transparency>=0.12 and part.Transparency<=0.96)
    if shape and (likelyFence or plainSlat) then return true,"geometry" end
    -- Thin horizontal rails may form a fence even without a useful part name.
    local horizontalRail=sz.Y<=0.65 and thin<=0.52 and wide>=1.40
        and wide<=72 and (likelyFence or part.Material==Enum.Material.Plastic)
    if horizontalRail then return true,"horizontal-rail" end

    if thin<=1.55 and part.Transparency>=0.96 then
        return true,"invisible-panel"
    end
    return false,"none"
end

local function bindCharacter(char)
    character=char
    humanoid=char and char:FindFirstChildOfClass("Humanoid") or nil
    root=char and char:FindFirstChild("HumanoidRootPart") or nil
    rayParams.FilterDescendantsInstances=char and {char} or {}
    overlapParams.FilterDescendantsInstances=char and {char} or {}
    lastContact=nil
    cachedContact=nil
    lastContactUntil=-math.huge
    lastScanAt=-math.huge
    lastOverlapAt=-math.huge
    lastChord="-"
    lastFacing=Vector3.zero
    lastContactHopAt=-math.huge
    lastMicroHopAt=-math.huge
    lastNearFenceAt=-math.huge
    nextMagnetAt=-math.huge
    hopArmed=true
end
bindCharacter(player.Character)
characterConnection=player.CharacterAdded:Connect(bindCharacter)

local function readBridge()
    local b=env.PCKeyboardTouchBridgeV52
    if type(b)=="table" and type(b.GetState)=="function" then
        local ok,state=pcall(b.GetState)
        if ok and type(state)=="table" then
            return tostring(state.chord or "-"),
                tonumber(state.analogX) or 0,
                tonumber(state.analogZ) or 0,
                state.sweepActive==true
        end
    end
    return "-",0,0,false
end

local function intentFromChord(chord)
    local cam=Workspace.CurrentCamera
    if not cam then return flatUnit(humanoid.MoveDirection) end
    local forward=flatUnit(cam.CFrame.LookVector)
    local right=flatUnit(cam.CFrame.RightVector)
    local x,z=0,0
    -- Preserve exact PC key chords from the ORIGINAL bridge.
    if string.find(chord,"W",1,true) then z+=1 end
    if string.find(chord,"S",1,true) then z-=1 end
    if string.find(chord,"A",1,true) then x-=1 end
    if string.find(chord,"D",1,true) then x+=1 end
    local wanted=forward*z+right*x
    if wanted.Magnitude>1e-5 then return wanted.Unit end
    return flatUnit(humanoid.MoveDirection)
end

local function visualFacingIntent(desired,chord,analogX,analogZ,sweepActive)
    if sweepActive then return desired end -- original A/D sweep stays exact
    if chord~="W+A" and chord~="W+D" and chord~="A+S" and chord~="S+D" then
        return desired -- pure A/D/W/S stay pure
    end
    local cam=Workspace.CurrentCamera
    if not cam then return desired end
    local a=flatUnit(flatUnit(cam.CFrame.RightVector)*analogX
        -flatUnit(cam.CFrame.LookVector)*analogZ)
    if a.Magnitude<0.1 or desired:Dot(a)<0.65 then return desired end
    return flatUnit(desired*0.72+a*0.28)
end

local function candidateContact(hit,origin)
    if not hit then return nil end
    local valid,kind=isFenceLike(hit.Instance)
    local dist=(hit.Position-origin).Magnitude
    if dist<lastRayHitDistance then
        lastRayHitDistance=dist
        lastRayHitName=hit.Instance and hit.Instance:GetFullName() or "?"
    end
    if not valid or dist>CONTACT_MAX_DISTANCE
        or math.abs(hit.Normal.Y)>WALL_NORMAL_Y_MAX then return nil end
    local normal=flatUnit(hit.Normal)
    if normal.Magnitude<0.2 then return nil end
    -- Ensure the normal points from the wall toward the player.
    if normal:Dot(flat(origin-hit.Position))<0 then normal=-normal end
    return {
        normal=normal,
        distance=dist,
        instance=hit.Instance,
        name=hit.Instance:GetFullName(),
        mode=kind,
        held=false
    }
end

local function bestContact()
    if not root then return nil end
    lastRayHitName="-"
    lastRayHitDistance=math.huge
    local best=nil
    local rootPos=root.Position
    for _,height in ipairs(WALL_HEIGHTS) do
        local origin=rootPos+Vector3.new(0,height,0)
        for _,dir in ipairs(radialDirections) do
            local hit=Workspace:Raycast(origin,dir*WALL_RADIUS,rayParams)
            local candidate=candidateContact(hit,origin)
            if candidate then
                -- Tiny preference for a stable contact normal at crowded corners.
                local score=candidate.distance
                if lastContact and candidate.normal:Dot(lastContact.normal)<0.70 then
                    score+=0.16
                end
                if not best or score<best.score then
                    candidate.score=score
                    best=candidate
                end
            end
        end
    end
    if best then return best end

    -- Overlap fallback: narrow rails and slats between the radial rays.
    -- Rate-limit the broader shape query on mobile to avoid FPS drops.
    if os.clock()-lastOverlapAt<0.055 then return nil end
    lastOverlapAt=os.clock()
    -- Confirm a direct unobstructed ray before using a nearby part.
    local ok,parts=pcall(function()
        return Workspace:GetPartBoundsInRadius(rootPos,WALL_RADIUS,overlapParams)
    end)
    if not ok or type(parts)~="table" then return nil end
    for _,part in ipairs(parts) do
        local valid,kind=isFenceLike(part)
        if valid then
            local got,point=pcall(function()
                return part:GetClosestPointOnSurface(rootPos)
            end)
            if got and typeof(point)=="Vector3" then
                local diff=flat(rootPos-point)
                local dist=diff.Magnitude
                if dist>0.08 and dist<CONTACT_MAX_DISTANCE
                    and math.abs(rootPos.Y-point.Y)<=2.7 then
                    local origin=rootPos+Vector3.new(0,0.12,0)
                    local direction=point-origin
                    if direction.Magnitude>0.08 then
                        local hit=Workspace:Raycast(origin,direction.Unit*(direction.Magnitude+0.14),rayParams)
                        if hit and hit.Instance==part then
                            local normal=flatUnit(hit.Normal)
                            if normal.Magnitude<0.2 then normal=diff.Unit end
                            if normal:Dot(diff)<0 then normal=-normal end
                            local candidate={
                                normal=normal,
                                distance=dist,
                                instance=part,
                                name=part:GetFullName(),
                                mode=kind.."-overlap",
                                held=false,
                                score=dist
                            }
                            if not best or candidate.score<best.score then best=candidate end
                        end
                    end
                end
            end
        end
    end
    return best
end

local function getContact(now)
    if now-lastScanAt>=CONTACT_SCAN_INTERVAL then
        lastScanAt=now
        scanCount+=1
        cachedContact=bestContact()
        if cachedContact then
            lastContact=cachedContact
            lastContactUntil=now+CONTACT_GRACE_SECONDS
            if cachedContact.mode=="geometry" or cachedContact.mode=="geometry-overlap"
                or cachedContact.mode=="invisible-panel"
                or cachedContact.mode=="invisible-panel-overlap" then
                geometryContacts+=1
            end
        end
    end
    if cachedContact then return cachedContact end
    if lastContact and now<lastContactUntil then
        return {
            normal=lastContact.normal,
            distance=lastContact.distance,
            name=lastContact.name,
            mode=lastContact.mode,
            held=true
        }
    end
    return nil
end

local function smoothFacing(desired,dt)
    if desired.Magnitude<0.5 or not root or root.Anchored then return end
    local target=desired.Unit
    -- Smooth only facing. Do not filter the physics input or the old A/D keys.
    -- In a complete about-face, the avatar turns faster instead of feeling heavy.
    local forward=flatUnit(root.CFrame.LookVector)
    local dot=forward.Magnitude>0 and forward:Dot(target) or 1
    local response=dot<-0.55 and 0.050 or 0.067
    local alpha=1-math.exp(-dt/response)
    local frame=CFrame.lookAt(root.Position,root.Position+target)
    pcall(function()
        root.CFrame=root.CFrame:Lerp(frame,alpha)
    end)
end

local function applyAssist(contact,desired,changed,dt,now)
    if desired.Magnitude<=0.05 or not root or not humanoid then return end
    local normal=contact.normal
    if not normal or normal.Magnitude<0.5 then return end

    -- CRITICAL V3 fix: if the thumb points AWAY, never oppose its movement.
    local away=desired:Dot(normal)
    if away>0.12 then
        outwardReleases+=1
        return
    end

    local current=root.AssemblyLinearVelocity
    local horizontal=flat(current)
    local currentNormalSpeed=horizontal:Dot(normal)
    local tangentVelocity=horizontal-normal*currentNormalSpeed
    local desiredTangent=desired-normal*away
    local tangentMagnitude=desiredTangent.Magnitude

    local correctedTangent=tangentVelocity
    local reversing=false
    if tangentMagnitude>0.10 then
        local along=desiredTangent.Unit
        reversing=tangentVelocity.Magnitude>0.12
            and tangentVelocity:Dot(along)<-0.12
        local targetSpeed=math.max(tangentVelocity.Magnitude,
            math.max(0,humanoid.WalkSpeed)*WALK_SEED_FACTOR)
        local targetTangent=along*targetSpeed
        -- Full response when reversing along a fence: no old-direction brake.
        local response=humanoid.FloorMaterial==Enum.Material.Air and 0.07 or 0.045
        local steerAlpha=reversing and 1 or (1-math.exp(-dt/response))
        if contact.held then steerAlpha*=0.65 end
        correctedTangent=tangentVelocity:Lerp(targetTangent,steerAlpha)
        if reversing then reversalFrames+=1 end
    end

    -- A small inward hold to keep contact with the rail while sliding.
    -- This is NEVER applied when the player deliberately moves outward.
    local heldScale=contact.held and 0.48 or 1
    local dynamicHold=math.min(MAGNET_SPEED_CAP,
        MAGNET_INWARD_SPEED+horizontal.Magnitude*0.035)
    -- A brief release after the light impact lets the player visibly detach
    -- from the grid before the adhesion reconnects.
    if now<nextMagnetAt then dynamicHold=0 end
    local targetNormalSpeed=-dynamicHold*heldScale
    local normalAlpha=1-math.exp(-dt/MAGNET_RESPONSE)
    local correctedNormal=currentNormalSpeed
    if now>=nextMagnetAt and correctedNormal>targetNormalSpeed then
        correctedNormal+=(targetNormalSpeed-correctedNormal)*normalAlpha
    end
    local corrected=correctedTangent+normal*correctedNormal

    -- No speed multiplication on direction switches. Prevent magnet spikes.
    local oldSpeed=horizontal.Magnitude
    local allowed=math.max(oldSpeed,humanoid.WalkSpeed*1.06)+0.75
    if corrected.Magnitude>allowed and corrected.Magnitude>0 then
        corrected=corrected.Unit*allowed
    end

    if (corrected-horizontal).Magnitude>=0.025 then
        pcall(function()
            root.AssemblyLinearVelocity=Vector3.new(corrected.X,current.Y,corrected.Z)
        end)
        assistedFrames+=1
        magnetFrames+=1
    end

    -- Original small hop preserved, but not when stepping away from the fence.
    if MICRO_HOP_ENABLED and changed and not contact.held
        and humanoid.FloorMaterial~=Enum.Material.Air
        and now-lastMicroHopAt>=MICRO_HOP_COOLDOWN
        and now-lastContactHopAt>=HOP_COOLDOWN_SECONDS then
        local v=root.AssemblyLinearVelocity
        pcall(function()
            root.AssemblyLinearVelocity=Vector3.new(v.X,MICRO_HOP_SPEED,v.Z)
        end)
        lastMicroHopAt=now
    end
end


-- Arms after leaving the actual near-contact area, not after a key release.
-- This prevents repeated boosts while the avatar remains pressed against a rail.
local function considerContactHop(contact,desired,now)
    if not CONTACT_HOP_ENABLED or not root or not humanoid then return end
    local near=contact and not contact.held
        and type(contact.distance)=="number"
        and contact.distance<=HOP_MAX_CONTACT_DISTANCE

    if not near then
        if now-lastNearFenceAt>=HOP_REARM_LOST_SECONDS then
            hopArmed=true
        end
        return
    end
    lastNearFenceAt=now
    if not hopArmed or now-lastContactHopAt<HOP_COOLDOWN_SECONDS then return end
    if desired.Magnitude<0.15 then return end

    local normal=contact.normal
    if not normal or normal.Magnitude<0.5 then return end
    local inwardIntent=desired:Dot(normal)
    if inwardIntent>=-0.18 then return end

    local velocity=root.AssemblyLinearVelocity
    local horizontal=flat(velocity)
    local inwardVelocity=horizontal:Dot(normal)
    local horizontalSpeed=horizontal.Magnitude
    local grounded=humanoid.FloorMaterial~=Enum.Material.Air

    -- Ground impacts can be slow after collision. Air contacts must be moving
    -- toward the rail, so sliding nearby does not repeatedly grant an air jump.
    if grounded then
        if horizontalSpeed<1.8 then return end
    elseif inwardVelocity>=-0.35 or horizontalSpeed<3.0 then
        return
    end

    local gravity=math.max(60,Workspace.Gravity)
    local targetY=math.clamp(gravity*(HOP_TARGET_AIRTIME*0.5),10.0,19.5)
    -- Never boost an already-strong upward jump.
    if velocity.Y>=targetY-1.25 then return end

    -- Detach just slightly, stay in air briefly, then let the magnet reconnect.
    -- The outward nudge is small enough to avoid flinging the player.
    local nextHorizontal=horizontal-normal*inwardVelocity
        +normal*HOP_OUTWARD_SPEED
    local impulseApplied=pcall(function()
        root.AssemblyLinearVelocity=Vector3.new(
            nextHorizontal.X,
            math.max(velocity.Y,targetY),
            nextHorizontal.Z
        )
    end)
    if not impulseApplied then return end
    lastContactHopAt=now
    lastMicroHopAt=now
    nextMagnetAt=now+HOP_RELEASE_SECONDS
    hopArmed=false
    contactHopCount+=1
    if grounded then groundContactHops+=1 else airContactHops+=1 end
end

heartbeatConnection=RunService.Heartbeat:Connect(function(dtFromHeartbeat)
    if not enabled then return end
    if character~=player.Character then bindCharacter(player.Character) end
    if character and (not humanoid or humanoid.Parent~=character or not root or root.Parent~=character) then
        local nextHum=character:FindFirstChildOfClass("Humanoid")
        local nextRoot=character:FindFirstChild("HumanoidRootPart")
        if nextHum~=humanoid or nextRoot~=root then bindCharacter(character) end
    end
    if not humanoid or not root then return end
    if humanoid.Health<=0 or humanoid.Sit or root.Anchored then return end

    local now=os.clock()
    local dt=math.clamp(dtFromHeartbeat or now-lastHeartbeatAt,1/240,0.05)
    lastHeartbeatAt=now
    local chord,rawX,rawZ,sweepActive=readBridge()
    local desired=intentFromChord(chord)
    local changed=(chord~=lastChord and lastChord~="-" and chord~="-")
    lastChord=chord

    -- Only orientation gets analog polish. The input/key engine is untouched.
    local visual=visualFacingIntent(desired,chord,rawX,rawZ,sweepActive)
    if visual.Magnitude>0.05 then
        smoothFacing(visual,dt)
    else
        lastFacing=Vector3.zero
    end
    if desired.Magnitude<=0.05 then
        considerContactHop(nil,desired,now)
        return
    end

    local contact=getContact(now)
    considerContactHop(contact,desired,now)
    if not contact then
        noContactFrames+=1
        return
    end
    applyAssist(contact,desired,changed,dt,now)
end)

env.LegacyGridContactAssistV1={
    Version="5.1-v31-strong-grip-contact-air-hop",
    Enabled=enabled,
    GetState=function()
        return {
            enabled=enabled,
            chord=lastChord,
            assistedFrames=assistedFrames,
            magnetFrames=magnetFrames,
            reversalFrames=reversalFrames,
            geometryContacts=geometryContacts,
            noContactFrames=noContactFrames,
            scanCount=scanCount,
            overlapPartLimit=overlapParams.MaxParts,
            mode=lastContact and lastContact.mode or "none",
            lastHitName=lastContact and lastContact.name or "-",
            lastRayHitName=lastRayHitName,
            lastRayHitDistance=lastRayHitDistance,
            lastNormal=lastContact and lastContact.normal or Vector3.zero,
            wallRadius=WALL_RADIUS,
            scanInterval=CONTACT_SCAN_INTERVAL,
            microHopEnabled=MICRO_HOP_ENABLED,
            contactHopEnabled=CONTACT_HOP_ENABLED,
            contactHopCount=contactHopCount,
            groundContactHops=groundContactHops,
            airContactHops=airContactHops,
            hopTargetAirtime=HOP_TARGET_AIRTIME,
            hopReleaseSeconds=HOP_RELEASE_SECONDS,
            magnetInwardSpeed=MAGNET_INWARD_SPEED,
            magnetSpeedCap=MAGNET_SPEED_CAP,
            outwardReleases=outwardReleases,
            hopArmed=hopArmed
        }
    end,
}

env.__LegacyGridContactAssistV1Cleanup=function()
    enabled=false
    if heartbeatConnection then pcall(function() heartbeatConnection:Disconnect() end) end
    if characterConnection then pcall(function() characterConnection:Disconnect() end) end
    if env.LegacyGridContactAssistV1 and
        env.LegacyGridContactAssistV1.Version=="5.1-v31-strong-grip-contact-air-hop" then
        env.LegacyGridContactAssistV1=nil
    end
    env.__LegacyGridContactAssistV1Cleanup=nil
end
end
modules.cursor=function(...)
-- Cursor appearance only. Never changes input capability, position or behavior.
local UserInputService=game:GetService("UserInputService")
local Players=game:GetService("Players")
local env=getgenv()
local previousCleanup=env.__PCCursorVisualV31Cleanup
if type(previousCleanup)=="function" then previousCleanup() end

local previous=UserInputService.MouseIconEnabled
assert(type(previous)=="boolean","MouseIconEnabled unavailable")
local running,hidden=true,true
local connections={}
local resets=0
local lastError=nil
local function enforce()
    if not running or not hidden then return end
    local ok,message=pcall(function()
        if UserInputService.MouseIconEnabled then
            UserInputService.MouseIconEnabled=false
            resets+=1
        end
    end)
    if not ok then lastError=tostring(message) end
end
local function restore()
    if UserInputService.MouseIconEnabled==false then UserInputService.MouseIconEnabled=previous end
end
local api={}
function api.SetEnabled(value)
    if not running then return false,"stopped" end
    hidden=value~=false
    if hidden then enforce() else pcall(restore) end
    return hidden
end
function api.GetState()
    return {enabled=running and hidden,visualOnly=true,mouseIconEnabled=UserInputService.MouseIconEnabled,
        hiddenResets=resets,lastError=lastError}
end
local cleanup
cleanup=function()
    if not running then return end
    running=false
    for _,connection in ipairs(connections) do pcall(function() connection:Disconnect() end) end
    pcall(restore)
    if env.PCCursorVisualV31==api then env.PCCursorVisualV31=nil end
    if env.__PCCursorVisualV31Cleanup==cleanup then env.__PCCursorVisualV31Cleanup=nil end
end
api.Stop=cleanup
local ok,message=pcall(function()
    connections[#connections+1]=UserInputService:GetPropertyChangedSignal("MouseIconEnabled"):Connect(enforce)
    connections[#connections+1]=Players.LocalPlayer.CharacterAdded:Connect(enforce)
    enforce()
end)
if not ok then cleanup() error(message) end
env.PCCursorVisualV31=api
env.__PCCursorVisualV31Cleanup=cleanup
return api
end
local start=(function()
-- The packer passes the preserved components as local functions. No module fetches.
return function(modules)
    local env=getgenv()
    if env.PCMovementV32 then return env.PCMovementV32 end
    if env.__PCMovementV31PreservedInstall then
        return nil,"A instalação anterior de PC Movement ainda está em andamento."
    end

    local players=game:GetService("Players")
    local api={Version="3.2-adaptive"}
    local state="starting"
    local phaseBusy=true
    local stopRequested=false
    local lease={}
    local stopSlots={}
    local playerGui,overlay,joystick,knob,jump,repairJob,repairConnection
    local repairs,repairFailures=0,0
    local assistMode="starting"
    local cursorError
    local LEGACY_OWNERS={"PCMovementAssistV31Preserved","PCMovementAssistV31","PCMovementAssistV3",
        "PCMovementAssistV2","PCMovementRebuild"}
    local LEGACY_SLOTS={"__PCCursorVisualV31Cleanup","__PCModeLockCleanup","__PCRobloxNativeVisualV5Cleanup",
        "__PCKeyboardTouchBridgeV52Cleanup","__PCKeyboardControllerWakeV5Cleanup",
        "__PCCameraTouchRightHalfGateV5Cleanup","__LegacyGridContactAssistV1Cleanup",
        "__PCCrouchToggleV59Cleanup","__PCIndependentJoystickCleanup","__PCKeyboardTouchBridgeV5Cleanup",
        "__PCSelectiveWASDCleanup","__PCClassicNativeKeysV3Cleanup","__PCClassicNativeKeysCleanup","__PCClassicWASDCleanup"}
    local LOCK="__PCModeLockCleanup"
    local WAKE="__PCKeyboardControllerWakeV5Cleanup"
    local CAMERA="__PCCameraTouchRightHalfGateV5Cleanup"
    local BRIDGE="__PCKeyboardTouchBridgeV52Cleanup"
    local VISUAL="__PCRobloxNativeVisualV5Cleanup"
    local CURSOR="__PCCursorVisualV31Cleanup"
    local ASSIST="__LegacyGridContactAssistV1Cleanup"
    local OVERLAY="PCKeyboardTouchBridgeV52Overlay"

    local function disconnectSlot(slot)
        local owned=stopSlots[slot]
        stopSlots[slot]=nil
        if owned and env[slot]==owned then
            local ok,message=pcall(owned)
            if not ok then warn("[PC Movement V3.2] cleanup "..slot..": "..tostring(message)) end
        end
    end

    local function freeLease()
        if env.__PCMovementV31PreservedInstall==lease then env.__PCMovementV31PreservedInstall=nil end
    end

    local function teardown()
        if repairConnection then repairConnection:Disconnect() repairConnection=nil end
        if repairJob then task.cancel(repairJob) repairJob=nil end
        for _,slot in ipairs({CURSOR,ASSIST,VISUAL,BRIDGE,CAMERA,WAKE,LOCK}) do disconnectSlot(slot) end
        overlay,joystick,knob,jump=nil,nil,nil,nil
        freeLease()
        if env.PCMovementV32==api then env.PCMovementV32=nil end
        if env.PCMovementAssistV31Preserved==api then env.PCMovementAssistV31Preserved=nil end
        if env.PCMovementAssistV31==api then env.PCMovementAssistV31=nil end
        state="stopped"
    end

    function api.Stop()
        if stopRequested then return end
        stopRequested=true
        state="stopping"
        if not phaseBusy then teardown() end
    end

    local function checkActive()
        if stopRequested then error("instalação cancelada",0) end
    end

    local function install(slot,init,...)
        checkActive()
        local before=env[slot]
        local ok,message=pcall(init,...)
        if type(env[slot])=="function" and env[slot]~=before then stopSlots[slot]=env[slot] end
        if not ok then error(message,0) end
        checkActive()
    end

    local function installOverlay()
        disconnectSlot(VISUAL)
        disconnectSlot(BRIDGE)
        install(BRIDGE,modules.bridge,modules.posture)
        install(VISUAL,modules.visual)
        overlay=assert(playerGui:FindFirstChild(OVERLAY))
        joystick=assert(overlay:FindFirstChild("PCJoystick"))
        knob=assert(joystick:FindFirstChild("Knob"))
        jump=assert(overlay:FindFirstChild("PCJump"))
    end

    local function installAssist(target)
        disconnectSlot(ASSIST)
        install(ASSIST,target=="original" and modules.originalAssist or modules.assist)
        assistMode=target
    end

    local function callComponent(slot,name,method,...)
        if not stopSlots[slot] or env[slot]~=stopSlots[slot] then return nil end
        local object=env[name]
        if type(object)=="table" and type(object[method])=="function" then
            return object[method](...)
        end
    end

    function api.GetState()
        return {version="3.2",build=api.Version,status=state,repairs=repairs,repairFailures=repairFailures,
            assistMode=assistMode,cursorError=cursorError,bridge=callComponent(BRIDGE,"PCKeyboardTouchBridgeV52","GetState"),
            assist=callComponent(ASSIST,"LegacyGridContactAssistV1","GetState"),pcLock=callComponent(LOCK,"PCModeLock","GetState"),
            keyboardWake=callComponent(WAKE,"PCKeyboardControllerWakeV5","GetState"),
            cameraGate=callComponent(CAMERA,"PCCameraTouchRightHalfGateV5","GetState")}
    end

    function api.SetCursorHidden(value)
        return callComponent(CURSOR,"PCCursorVisualV31","SetEnabled",value)
    end
    function api.SetDiagnostics(value)
        return callComponent(ASSIST,"LegacyGridContactAssistV1","SetDiagnostics",value)
    end
    function api.ExportDiagnostics(filename)
        return callComponent(ASSIST,"LegacyGridContactAssistV1","ExportDiagnostics",filename or "PCMovement_V32_Log.json")
    end
    function api.SetAssistMode(target)
        if state~="running" or phaseBusy or game.GameId~=3647333358 then return false,"assist unavailable" end
        if target~="light" and target~="original" then return false,"use light or original" end
        if target==assistMode then return true end
        phaseBusy=true
        env.__PCMovementV31PreservedInstall=lease
        local previous=assistMode
        local ok,message=pcall(installAssist,target)
        if not ok and not stopRequested then
            local restored,reason=pcall(installAssist,previous)
            if not restored then
                disconnectSlot(ASSIST)
                assistMode="failed"
                warn("[PC Movement V3.2] Assist rollback: "..tostring(reason))
            end
        end
        phaseBusy=false
        freeLease()
        if stopRequested then teardown() end
        return ok,message
    end

    local function scheduleRepair(delay)
        if repairJob or state~="running" then return end
        repairJob=task.delay(delay,function()
            repairJob=nil
            if state~="running" then return end
            if phaseBusy then scheduleRepair(0.25) return end
            phaseBusy=true
            env.__PCMovementV31PreservedInstall=lease
            local ok,message=pcall(installOverlay)
            phaseBusy=false
            freeLease()
            if stopRequested then teardown() return end
            if ok then
                repairs+=1
                repairFailures=0
            else
                disconnectSlot(VISUAL)
                disconnectSlot(BRIDGE)
                repairFailures+=1
                warn("[PC Movement V3.2] UI repair: "..tostring(message))
                if repairFailures<3 then scheduleRepair(3) end
            end
        end)
    end

    env.PCMovementV32=api
    env.__PCMovementV31PreservedInstall=lease
    local ok,message=pcall(function()
        for _,name in ipairs(LEGACY_OWNERS) do
            local owner=env[name]
            if type(owner)=="table" and type(owner.Stop)=="function" then pcall(owner.Stop) end
        end
        env.__PCMovementAssistV2Token=nil
        env.__PCMovementAssistV3Token=nil
        env.__PCMovementAssistV31Token=nil
        for _,slot in ipairs(LEGACY_SLOTS) do
            if type(env[slot])=="function" then pcall(env[slot]) end
        end
        env.PCMovementAssistV31Preserved=api
        env.PCMovementAssistV31=api

        local deadline=os.clock()+15
        local player,playerModule
        repeat
            checkActive()
            player=players.LocalPlayer
            playerGui=player and player:FindFirstChild("PlayerGui")
            local scripts=player and player:FindFirstChild("PlayerScripts")
            playerModule=scripts and scripts:FindFirstChild("PlayerModule")
            if playerGui and playerModule then break end
            if os.clock()>=deadline then error("PlayerGui/PlayerModule unavailable after 15 seconds") end
            task.wait(0.05)
        until false
        for _,object in ipairs(playerGui:GetDescendants()) do
            if object:IsA("UIScale") and object.Name=="PCCrouchPressVisualV59" then object:Destroy() end
        end
        install(LOCK,modules.lock,function() return not stopRequested end)
        install(CAMERA,modules.camera)
        install(WAKE,modules.wake)
        installOverlay()
        if game.GameId==3647333358 then
            installAssist("light")
        else
            assistMode="not-applicable"
        end
        local cursorOK,reason=pcall(install,CURSOR,modules.cursor)
        if not cursorOK then
            checkActive()
            disconnectSlot(CURSOR)
            cursorError=tostring(reason)
            warn("[PC Movement V3.2] cursor: "..cursorError)
        end
        repairConnection=playerGui.DescendantRemoving:Connect(function(node)
            if not overlay then return end
            if node==overlay or node==joystick or node==knob or node==jump then
                callComponent(BRIDGE,"PCKeyboardTouchBridgeV52","SuspendInput")
                scheduleRepair(1.25)
            end
        end)
    end)
    phaseBusy=false
    freeLease()
    if not ok or stopRequested then
        teardown()
        if stopRequested then return nil,"instalação cancelada" end
        error(message,0)
    end
    state="running"
    return api
end
end)()
return start(modules)
